-- 74 clearer openings; 60 optional transfer activities for M03-M11.
-- This follows the M01/M02 editorial migration. Same version and assessment IDs.
SET lock_timeout = '5s';
DO $editorial$
DECLARE
 curriculum jsonb := $curriculum$[{"module":"s01-m01","lesson":"l01-01","version":9,"base":"silk_road_editorial_20261003","title":null,"intro":{"body":"Ще започнеш от конкретен човешки проблем и ще прецениш къде AI може да помогне. Ще различиш убедителния отговор от проверения факт.","outcomes":["Описваш кой човек има затруднение и какво го спира.","Избираш малка задача с налични данни и ясен резултат.","Отделяш факт, предположение и липсваща информация."],"deliverable":"Описание на проблем, първо малко решение и списък с нужните проверки.","check":"Сравняваш избора си с учебната работилница: без график приемаме запитване, а часът остава за потвърждение."}},{"module":"s01-m01","lesson":"l01-02","version":9,"base":"silk_road_editorial_20261003","title":null,"intro":{"body":"Ще подготвиш задание, което AI може да изпълни без да допълва липсващите условия по свое усмотрение. Ще упражниш и поправката на грешен резултат.","outcomes":["Даваш цел, източници, ограничения и форма на резултата.","Разпознаваш чужда инструкция в получен файл.","Проверяваш черновата с непълни и противоречиви данни."],"deliverable":"Задание за собствена идея или учебния случай, плюс четири тестови входа.","check":"В резултата няма измислена цена, наличност или право за изпращане на чужди данни."}},{"module":"s01-m01","lesson":"l01-03","version":9,"base":"silk_road_editorial_20261003","title":null,"intro":{"body":"Ще сравниш AI решения по една и съща задача. Изборът ще включва качеството, достъпа и времето за проверка, а не само скоростта на първия отговор.","outcomes":["Различаваш модел, приложение и свързан инструмент.","Записваш наличното в конкретен план и акаунт.","Сравняваш целия процес, включително поправките."],"deliverable":"Кратка карта за избор на инструмент с дата, ограничения и проверен резултат.","check":"Използваш еднакъв вход и критерии; можеш да работиш с предоставените резултати без платен план."}},{"module":"s01-m01","lesson":"l01-04","version":9,"base":"silk_road_editorial_20261003","title":null,"intro":{"body":"Ще превърнеш повтаряща се задача в малък работен процес. Ще разбереш какво може да прави агентът, какво му разрешаваш и кога действието трябва да спре.","outcomes":["Разделяш вход, предложение, проверка и действие.","Обясняваш API и MCP като начини системи да обменят информация.","Задаваш ограничени права и условие за човешко решение."],"deliverable":"Схема на една полезна услуга с нормален случай, отказ, грешка и повторение.","check":"Можеш да проследиш какво е станало и да покажеш кой има право за всяко действие."}},{"module":"s01-m02","lesson":"l02-01","version":7,"base":"silk_road_editorial_20261003","title":null,"intro":{"body":"Ще подредиш страница според въпросите на посетителя. Първата версия ще описва действителна услуга и действие, което може да бъде изпълнено.","outcomes":["Избираш една аудитория, едно предложение и основно действие.","Поставяш цена, обхват и следваща стъпка на разбираемо място.","Различаваш показана форма от действително получена заявка."],"deliverable":"План на страница и ясно задание за избрания редактор или AI.","check":"Посетителят намира услугата и условията; текстът не обещава час без проверка на графика."}},{"module":"s01-m02","lesson":"l02-02","version":7,"base":"silk_road_editorial_20261003","title":null,"intro":{"body":"Ще направиш важния текст удобен за четене на телефон. Ще подредиш заглавията, условията и действието така, че човек да ги намира без отгатване.","outcomes":["Разграничаваш заглавие, обяснение, цена и условие.","Избираш четим шрифт с подходяща кирилица.","Проверяваш тесен екран и увеличение на текста."],"deliverable":"Типографска подредба и протокол за намиране на цена, обхват и срок.","check":"Нищо важно не се отрязва, скрива или губи върху снимка."}},{"module":"s01-m02","lesson":"l02-03","version":7,"base":"silk_road_editorial_20261003","title":null,"intro":{"body":"Ще избереш визуална посока с ясна причина. Ще използваш архетипа за историята на продукта и цветовете за четимост и последователност.","outcomes":["Обясняваш архетипа като творческа рамка.","Задаваш роли на фон, текст, акцент и състояния.","Отделяш асоциация от измерим контраст и доказан ефект."],"deliverable":"Две палитри с аргумент за избора и проверени двойки текст–фон.","check":"Посочваш границите на модела; цветът сам не е обещание за повече продажби."}},{"module":"s01-m02","lesson":"l02-04","version":7,"base":"silk_road_editorial_20261003","title":null,"intro":{"body":"Ще провериш как страницата се използва в неудобен момент: малък екран, клавиатура, забавяне или прекъсване. Ще поправяш конкретен дефект.","outcomes":["Проверяваш меню, полета и бутони на тесен екран.","Пазиш въведеното при неуспех.","Разпознаваш повторна заявка по нейния идентификатор."],"deliverable":"Мобилен тест с нормален случай, грешка, забавяне и повторение.","check":"Има ясно съобщение за състоянието и правилен брой получени учебни записи."}},{"module":"s01-m02","lesson":"l02-05","version":7,"base":"silk_road_editorial_20261003","title":null,"intro":{"body":"Ще подбереш изображения, които обясняват услуга или продукт. Ще провериш произхода, употребата и начина, по който ги представяш.","outcomes":["Назоваваш въпроса, на който отговаря всеки кадър.","Различаваш реална работа от синтетична илюстрация.","Проверяваш изрязване, файл, описание и зареждане."],"deliverable":"Списък с визуали, предназначение, произход и липсващи материали.","check":"Илюстрацията е означена и не се представя за клиентски резултат."}},{"module":"s01-m02","lesson":"l02-06","version":7,"base":"silk_road_editorial_20261003","title":null,"intro":{"body":"Ще свържеш текста на бутона с очакването на човека и действителния процес след натискане. Ще измериш получено запитване отделно от резервация.","outcomes":["Уточняваш какво човек получава след действието.","Намаляваш ненужното усилие и неясните условия.","Проверяваш успех, грешка, забавяне и повторение."],"deliverable":"Призив за действие, съобщения на формата и приемателни проверки.","check":"Обещанието съвпада със записа; липсващ график не се заменя с убедителен текст."}},{"module":"s01-m02","lesson":"l02-07","version":7,"base":"silk_road_editorial_20261003","title":null,"intro":{"body":"Ще откриеш конкретно забавяне и ще провериш дали поправката помага. Ще пазиш разликата между лабораторен тест и резултат за реални посетители.","outcomes":["Сравняваш една и съща страница при сходни условия.","Записваш променения файл и измерването.","Проверяваш дали функциите остават работещи."],"deliverable":"Отчет преди и след една промяна, с посочени условия и ограничения.","check":"Ускорението не идва от премахване на нужно съдържание или неработеща форма."}},{"module":"s01-m02","lesson":"l02-08","version":7,"base":"silk_road_editorial_20261003","title":null,"intro":{"body":"Ще подредиш маршрут, по който човек намира нужното и довършва задачата си. Ще провериш страницата от различни начални точки.","outcomes":["Назоваваш менюто според очакваното съдържание.","Проследяваш пътя до цена, условия и заявка.","Записваш точните стъпки при затруднение."],"deliverable":"Два проверени маршрута и списък с поправки на навигацията.","check":"Действието е достижимо и от началната страница, и от свързан материал."}},{"module":"s01-m02","lesson":"l02-09","version":7,"base":"silk_road_editorial_20261003","title":null,"intro":{"body":"Ще подкрепиш обещанието с доказателство, което действително имаш. Ще представиш нов продукт честно дори когато още няма клиентска история.","outcomes":["Съпоставяш твърдение, доказателство и ограничение.","Означаваш учебен проект, демонстрация и илюстрация.","Проверяваш произхода и разрешената употреба."],"deliverable":"Карта на публичните твърдения с основание за всяко от тях.","check":"Няма измислен отзив, число за клиенти или гаранция без доказателство."}},{"module":"s01-m02","lesson":"l02-10","version":7,"base":"silk_road_editorial_20261003","title":null,"intro":{"body":"Ще провериш страницата от действителния адрес до получения запис. Ще разграничиш учебен прототип, свързана услуга и готовност за реални ползватели.","outcomes":["Изпълняваш тестове за успех, грешка, забавяне и повторение.","Проверяваш адрес, факти и ограничени права.","Предаваш проверена версия с открити ограничения."],"deliverable":"Страница и протокол за приемане, с посочен commit или локална версия.","check":"Всяко успешно действие има очаквания запис; непроверените връзки са ясно отбелязани."}},{"module":"s01-m03","lesson":"l03-01","version":7,"base":"silk_road_final_20260924","title":"Търсения и въпроси на клиента","intro":{"body":"Ще използваш търсенето като следа за нуждата на човека. Ще групираш въпроси и ще избереш страница, която може честно да им отговори.","outcomes":["Разделяш подготовка, сравнение и търсене на контакт.","Отделяш услуги, които бизнесът не предлага.","Приоритизираш без измислен обем на търсене."],"deliverable":"Карта въпрос–страница за собствена идея или учебен случай.","check":"Всяка група получава подходящ отговор и ясно отбелязани неизвестни."},"context_title":"Моментът зад търсенето","context":{"body":"Учебна работилница във Велико Търново предлага ремонт на велосипеди. Имаме три фрази: „как да проверя спирачките“, „ремонт на велосипед цена“ и „телефон на работилницата“. Първата може да води към безопасен общ наръчник и граница кога да потърсим специалист. Втората иска обхват и начин за определяне на цената. Третата иска проверен контакт. Не знаем броя търсения или бюджета на тези хора.\n\nAI може да предложи групи, но ти проверяваш дали услугата съществува и дали отговорът съответства на въпроса. За своя бъдещ продукт събери пет въпроса от предоставени данни или разрешени наблюдения. Запиши отделно точната фраза, предполагаемата нужда и неизвестното.","sources":[]},"exercise":{"type":"matching","content":{"body":"Свържи учебното търсене с най-подходящия първи отговор.","left":[{"id":"learn","text":"Как да проверя спирачките?"},{"id":"compare","text":"Ремонт на велосипед цена"},{"id":"reach","text":"Телефон на работилницата"}],"right":[{"id":"rreach","text":"Проверен контакт и условия за връзка."},{"id":"rcompare","text":"Обхват и начин за уточняване на цената."},{"id":"rlearn","text":"Наръчник с ограничения и кога е нужен специалист."}]},"evaluation":{"matches":{"learn":"rlearn","compare":"rcompare","reach":"rreach"}},"feedback":{"explanation":"Примерно решение: Как да проверя спирачките? → Наръчник с ограничения и кога е нужен специалист.; Ремонт на велосипед цена → Обхват и начин за уточняване на цената.; Телефон на работилницата → Проверен контакт и условия за връзка."}}},{"module":"s01-m03","lesson":"l03-02","version":7,"base":"silk_road_final_20260924","title":"Оптимизация на съдържанието на страницата","intro":{"body":"Ще подготвиш страница, чието заглавие, основен текст и действие обещават едно и също.","outcomes":["Пишеш ясно заглавие и начало.","Свързваш секциите с въпросите на посетителя.","Посочваш липсващите факти преди публикуване."],"deliverable":"Редакционно задание за една страница с проверки за приемане.","check":"Цената, срокът и бутонът съответстват на предоставените условия."},"context_title":"Първо обещанието, после настройката","context":{"body":"Учебният продукт е страница за ремонт. Заглавието обещава „цени“, но съдържанието показва само общи похвали. Първата поправка е конкретно обяснение как се определя цената и какво още трябва да бъде проверено. Добавянето на търсени думи не попълва липсата.\n\nНапиши два варианта със същите известни факти. В единия започни от услугата, в другия — от въпроса на човека. Провери дали читателят разбира обхвата и следващата стъпка. Това сравнение оценява яснота; за промяна в трафик или продажби трябват отделни наблюдения. Не приемай предложени от AI суми като фирмени условия.","sources":[]},"exercise":{"type":"scenario","content":{"prompt":"Заглавието обещава точна цена на ремонта, но бизнесът определя цена след преглед. Кой вариант е последователен?","options":[{"id":"range","label":"AI избира убедителна средна цена."},{"id":"process","label":"Описваме как се определя цената и приемаме запитване за преглед."},{"id":"keyword","label":"Повтаряме „цена“ още пет пъти."}]},"evaluation":{"correct":"process"},"feedback":{"explanation":"Описанието трябва да следва действителното определяне на цена. Честата дума и правдоподобното число не дават липсващия факт."}}},{"module":"s01-m03","lesson":"l03-03","version":7,"base":"silk_road_final_20260924","title":null,"intro":{"body":"Ще провериш къде действително се предлага услугата и как човек достига до бизнеса.","outcomes":["Разделяш физически адрес и обслужван район.","Проверяваш противоречиви контакти при източника.","Оставяш непотвърденото работно време за уточнение."],"deliverable":"Регистър на местните данни и подреден план за поправки.","check":"Не добавяш офис или график само за да присъстваш в друг град."},"context_title":"Къде човек може действително да отиде","context":{"body":"Работилницата е във Велико Търново и може да вземе велосипед от Павликени след уговорка. Това са различни условия. Човек от Павликени трябва да разбере как се заявява вземане, кой уточнява датата и как се определя разходът. Не му показваме измислен местен офис.\n\nЗа собствен продукт направи главен запис на данните: проверен адрес, контакт, район и начин на обслужване. Посочи източник и дата. Ако AI или стар материал противоречи на собственика, първо уточняваш факта. Разпространяваш поправката към собствените страници и профили, след което проверяваш действителния маршрут за контакт.","sources":[]},"exercise":{"type":"scenario","content":{"prompt":"За Павликени има само вземане след уговорка. Какво пише на страницата?","options":[{"id":"visit","label":"Посети офиса ни в Павликени."},{"id":"pickup","label":"Вземане от Павликени след уточняване на дата и условия."},{"id":"hours","label":"Всеки ден от 9 до 18 ч., без предоставен график."}]},"evaluation":{"correct":"pickup"},"feedback":{"explanation":"Показваме потвърдения начин на обслужване. Адресът и работното време не се извеждат от желанието за местна видимост."}}},{"module":"s01-m03","lesson":"l03-04","version":7,"base":"silk_road_final_20260924","title":null,"intro":{"body":"Ще различиш технически валидно маркиране от вярно описание на бизнеса.","outcomes":["Съпоставяш данните с видимата страница.","Премахваш неподкрепени рейтинг и адрес.","Проверяваш синтаксис, смисъл и ограничения."],"deliverable":"План за структурирани данни само с проверени факти.","check":"Валиден тест не се представя като гаранция за показване в търсене."},"context_title":"Маркирането не създава доказателството","context":{"body":"Структурираните данни описват информация във форма за системите. Ако няма клиентски оценки, добавен рейтинг 4,9 остава измислено твърдение и когато файлът е технически валиден. За нов продукт първо подготви видимата страница с действителен обхват и условия.\n\nУчебна проверка: прочети предложеното маркиране, намери всяко число и го свържи с източник. Непотвърдените полета се премахват или уточняват. После проверяваш техническата форма. Google посочва, че правилните структурирани данни дават възможност за определено представяне, но не гарантират такова. Същата граница стои и в предаването към клиент.","sources":[{"label":"Google: структурирани данни","url":"https://developers.google.com/search/docs/appearance/structured-data/intro-structured-data"}]},"exercise":{"type":"matching","content":{"body":"Разграничи трите проверки.","left":[{"id":"syntax","text":"Инструментът отчита валиден формат."},{"id":"truth","text":"Рейтингът няма предоставен източник."},{"id":"display","text":"Валидното маркиране ще се показва винаги."}],"right":[{"id":"rdisplay","text":"Гаранция, която не можем да дадем."},{"id":"rtruth","text":"Неподкрепен факт за премахване."},{"id":"rsyntax","text":"Техническа проверка."}]},"evaluation":{"matches":{"syntax":"rsyntax","truth":"rtruth","display":"rdisplay"}},"feedback":{"explanation":"Примерно решение: Инструментът отчита валиден формат. → Техническа проверка.; Рейтингът няма предоставен източник. → Неподкрепен факт за премахване.; Валидното маркиране ще се показва винаги. → Гаранция, която не можем да дадем."}}},{"module":"s01-m03","lesson":"l03-05","version":7,"base":"silk_road_final_20260924","title":null,"intro":{"body":"Ще оцениш какво действително е наблюдавано в AI отговор и какво още не може да се заключи.","outcomes":["Разделяш споменаване, цитирана страница и посещение.","Записваш продукт, въпрос, дата и условия.","Редактираш обещания за гарантирана AI видимост."],"deliverable":"Датиран отчет за наблюдавани отговори с граници на извода.","check":"Еднократен отговор не става доказателство за постоянна позиция."},"context_title":"Отговорът на AI е наблюдение с контекст","context":{"body":"GEO тук означава работа по полезно и достъпно съдържание, което може да бъде използвано в генеративно търсене. Не е една настройка за всички AI продукти. Google посочва, че за AI Overviews и AI Mode важат основните SEO принципи; няма специално изискване за нов AI файл или особена схема. Индексиране и показване не са гарантирани.\n\nЗа учебния си продукт запиши точния въпрос, използвания продукт, датата и получените връзки. Провери цитирания текст и дали той е актуален. Ако името е споменато, но посещенията не са известни, отчетът го казва. Полезната работа е поправка на конкретен отговор или достъп, а не обещание за първо място.","sources":[{"label":"Google: AI функции и сайтът","url":"https://developers.google.com/search/docs/appearance/ai-features"}]},"exercise":{"type":"calculator","content":{"prompt":"В 10 учебни AI отговора има 3 цитирания на страница. Какъв е делът на цитиранията в проценти?","label":"Изчислен резултат","unit":"%"},"evaluation":{"value":30},"feedback":{"explanation":"3/10×100 = 30%. Това е дял само в предоставения набор. Не показва посещения, продажби или постоянна видимост."}}},{"module":"s01-m03","lesson":"l03-06","version":7,"base":"silk_road_final_20260924","title":null,"intro":{"body":"Ще подготвиш текст, който помага на конкретен човек и пази точните условия на услугата.","outcomes":["Избираш въпрос и приложим отговор.","Отделяш съвет от фирмено условие.","Проверяваш предложената от AI чернова."],"deliverable":"Задание за статия, полезен увод и списък с неизвестни.","check":"Читателят получава конкретна помощ без измислени правила на бизнеса."},"context_title":"Собственият принос има работа за вършене","context":{"body":"Учебният въпрос е „Как да подготвя велосипеда за преглед?“. Имаме потвърдено, че трябва да се опише наблюдаваният проблем. Нямаме фирмено правило за доставка или разглобяване. Полезният текст дава списък с наблюдения и въпроси към работилницата, без да приписва непотвърдени процедури.\n\nAI може да подреди чернова. Ти добавяш предоставените факти, показваш липсите и проверяваш дали съветът може да бъде изпълнен. За собствен продукт избери един въпрос преди покупка и един след използване. Те могат да изискват различни материали. Броят генерирани статии не е доказателство за полезност.","sources":[]},"exercise":{"type":"scenario","content":{"prompt":"В черновата AI добавя задължителна предварителна такса, която липсва в източника. Кое следва?","options":[{"id":"publish","label":"Публикуваме, защото звучи професионално."},{"id":"remove","label":"Премахваме непотвърденото условие и питаме отговорния човек."},{"id":"repeat","label":"Питаме втори модел и приемаме съвпадащия отговор."}]},"evaluation":{"correct":"remove"},"feedback":{"explanation":"Два модела могат да повторят еднаква догадка. Условието се потвърждава от разрешения източник."}}},{"module":"s01-m03","lesson":"l03-07","version":7,"base":"silk_road_final_20260924","title":null,"intro":{"body":"Ще откриеш на коя стъпка страницата е недостъпна или неподходяща за публично търсене.","outcomes":["Различаваш достъп, откриване и индексиране.","Пазиш частните страници зад правилните ограничения.","Проверяваш стар адрес и пренасочване."],"deliverable":"Диагностична карта с поправка и проверка за всеки случай.","check":"Отварянето на публична услуга не прави клиентските данни публични."},"context_title":"Публична страница и частни записи","context":{"body":"Страницата за ремонт трябва да е достъпна за посетителя. Списъкът с лични запитвания има друг предназначен читател и други права. Решението „отвори всичко за търсачката“ смесва двете.\n\nПроследи публичния адрес в браузър без вход. После провери през разрешения тестов маршрут, че чужд посетител не вижда записите. За стар URL запиши какво трябва да се случи и провери действителния отговор след промяната. AI може да предложи настройки, но важни са поведението на адреса и защитата на данните. Не проверявай само предварителния преглед.","sources":[]},"exercise":{"type":"matching","content":{"body":"Свържи учебния ресурс с подходящото действие.","left":[{"id":"public","text":"Страница за услуга е скрита по грешка."},{"id":"private","text":"Списък с чужди запитвания."},{"id":"old","text":"Преместена услуга на стар адрес."}],"right":[{"id":"rold","text":"Проверено пренасочване към правилния нов адрес."},{"id":"rprivate","text":"Ограничен достъп за разрешените хора."},{"id":"rpublic","text":"Поправка на публичния достъп и нов тест."}]},"evaluation":{"matches":{"public":"rpublic","private":"rprivate","old":"rold"}},"feedback":{"explanation":"Примерно решение: Страница за услуга е скрита по грешка. → Поправка на публичния достъп и нов тест.; Списък с чужди запитвания. → Ограничен достъп за разрешените хора.; Преместена услуга на стар адрес. → Проверено пренасочване към правилния нов адрес."}}},{"module":"s01-m03","lesson":"l03-08","version":7,"base":"silk_road_final_20260924","title":null,"intro":{"body":"Ще оцениш предложение за външна връзка според аудитория, контекст и риск.","outcomes":["Разпознаваш релевантен материал и източник.","Отделяш читателска полза от обещание за класиране.","Проверяваш условията на платено партньорство."],"deliverable":"Кратка оценка на три възможности за външно присъствие.","check":"Не приемаш брой връзки като гарантиран бизнес резултат."},"context_title":"Защо някой би изпратил човек към твоя продукт","context":{"body":"Местен клуб по колоездене иска полезен списък с въпроси преди ремонт. Твоят учебен продукт може да даде проверен материал и подходящ маршрут към услугата. Това е конкретна причина за препратка. Пакет от неизвестни сайтове предлага само брой.\n\nЗа всяка възможност запиши кой я чете, защо материалът му помага и какво трябва да се договори. При платена публикация обозначаването и употребата се уточняват преди предаване. Не обещавай ефект върху класирането. След публикация проверяваш работещата връзка и наблюдаваните посещения отделно.","sources":[]},"exercise":{"type":"scenario","content":{"prompt":"Клубът иска проверен наръчник, а друг доставчик гарантира първо място срещу 1000 неизвестни връзки. Какво проверяваш първо?","options":[{"id":"count","label":"Кой предлага повече връзки."},{"id":"fit","label":"Кой достига подходящи хора с полезен материал и ясни условия."},{"id":"promise","label":"Коя гаранция звучи по-силно."}]},"evaluation":{"correct":"fit"},"feedback":{"explanation":"Приоритетът има основание в аудиторията и материала. Гаранцията и броят сами не установяват полза."}}},{"module":"s01-m03","lesson":"l03-09","version":7,"base":"silk_road_final_20260924","title":null,"intro":{"body":"Ще свържеш отчет за търсене с въпрос, който води до конкретна поправка.","outcomes":["Смяташ дял с правилния знаменател.","Разделяш факт от обяснение за причината.","Проверяваш дали посещенията водят до подходящо действие."],"deliverable":"Отчет с наблюдение, хипотеза, следваща проверка и действие.","check":"Същият период и начин на измерване стоят до числата."},"context_title":"Повече кликове, но какво следва","context":{"body":"Учебни данни: 200 посещения на страницата, 20 натискания на бутона и 8 получени валидни запитвания за един период. Бутонът и полученият запис са различни събития. Делът на валидните запитвания спрямо посещенията е 4%, а спрямо натисканията — 40%.\n\nИзбираш знаменателя според въпроса. За своя продукт назови всяко събитие и източника му. Ако записите липсват, първо проверяваш процеса. Не обяснявай разликата с психологията на хората, преди да знаеш дали формата работи. Отчетът трябва да показва и какво още не е измерено.","sources":[]},"exercise":{"type":"calculator","content":{"prompt":"От 200 учебни посещения има 8 получени валидни запитвания. Какъв е делът спрямо посещенията в проценти?","label":"Изчислен резултат","unit":"%"},"evaluation":{"value":4},"feedback":{"explanation":"8/200×100 = 4%. Натискането на бутона не е същият знаменател."}}},{"module":"s01-m03","lesson":"l03-10","version":7,"base":"silk_road_final_20260924","title":null,"intro":{"body":"Ще подредиш работа за търсене според човешката нужда, дефекта и наличното време.","outcomes":["Даваш предимство на блокиращ проблем.","Включваш проверката в часовете.","Отлагаш задача с ясно основание."],"deliverable":"Изпълним план с приоритет, отговорник и условие за приемане.","check":"Планът се побира във времето и не обещава позиция в търсачка."},"context_title":"Малък продукт с ограничено време","context":{"body":"Имаш 6 учебни часа. Поправката на грешния телефон отнема 1, проверката на формата 2, нова статия 4. Посетителите още не могат надеждно да се свържат. Двете първи задачи се побират и поправят действието; статията остава за следващ цикъл.\n\nЗа собствената идея подреди проблема, очакваната полза и доказателството за приемане. След работата провери адреса и получения запис, а не само отметката в списъка. Бъдещата видимост остава за измерване. Планът се променя, когато се появят нови факти или блокиращ дефект.","sources":[]},"exercise":{"type":"scenario","content":{"prompt":"Кои задачи приемаш първо при тези 6 часа?","options":[{"id":"article","label":"Само статията, защото носи повече текст."},{"id":"fix","label":"Телефонът и формата, с проверка на действителния резултат."},{"id":"all","label":"Всичко, като пропуснем проверката."}]},"evaluation":{"correct":"fix"},"feedback":{"explanation":"Първо възстановяваме изпълнимото действие. Не вместяваме 7 часа работа в 6 чрез пропускане на приемането."}}},{"module":"s01-m04","lesson":"l04-01","version":7,"base":"silk_road_final_20260924","title":null,"intro":{"body":"Ще избереш съдържание според въпроса и момента на човека, с реалистичен капацитет за производство.","outcomes":["Свързваш тема с подготовка, избор или използване.","Пазиш едни и същи факти във всички формати.","Отделяш време за проверка и обновяване."],"deliverable":"Седмичен план с цел, материал, действие и собственик.","check":"Всяка тема има конкретна работа за читателя."},"context_title":"Тема за човека точно сега","context":{"body":"Учебна работилница получава два вида въпроси: „какво включва прегледът“ и „как да разбера дали проблемът е спешен“. Единият помага за сравнение на услугата, другият — за безопасно ориентиране. Не ги събирай в общ рекламен текст.\n\nЗа бъдещия си продукт избери два момента и материал за всеки. Запиши известните факти и границата на съвета. Първият канал може да е собствена страница или предоставен учебен формат; не е нужен рекламен бюджет. Планът включва време за проверка и кой ще поправи условие, ако то се промени.","sources":[]},"exercise":{"type":"matching","content":{"body":"Свържи момента с полезното съдържание.","left":[{"id":"choose","text":"Сравнява какво включва прегледът."},{"id":"prepare","text":"Подготвя се за вече уговорен преглед."},{"id":"after","text":"Не разбира получения резултат."}],"right":[{"id":"rafter","text":"Обяснение и начин за уточняване."},{"id":"rprepare","text":"Кратък списък с нужните данни."},{"id":"rchoose","text":"Обхват и условия на услугата."}]},"evaluation":{"matches":{"choose":"rchoose","prepare":"rprepare","after":"rafter"}},"feedback":{"explanation":"Примерно решение: Сравнява какво включва прегледът. → Обхват и условия на услугата.; Подготвя се за вече уговорен преглед. → Кратък списък с нужните данни.; Не разбира получения резултат. → Обяснение и начин за уточняване."}}},{"module":"s01-m04","lesson":"l04-02","version":7,"base":"silk_road_final_20260924","title":null,"intro":{"body":"Ще замениш неясната похвала с проверимо описание на услуга и условия.","outcomes":["Назоваваш за кого е предложението.","Обясняваш включеното и следващото действие.","Премахваш недоказани суперлативи."],"deliverable":"Готово начало на страница с точни условия и бутон.","check":"Всеки факт може да се свърже с предоставения източник."},"context_title":"Яснотата дава възможност за избор","context":{"body":"Учебният текст „революционно решение за всеки“ не казва какво се получава. Имаме проверен обхват: страница за една услуга и форма за запитване. Това може да бъде описано точно, включително какво още не е свързано.\n\nНапиши два честни варианта за собствената си идея. Единият може да започне от проблема, другият — от предавания резултат. Фактите остават еднакви. Сравни дали читателят намира предназначението, обхвата и условието за действие. Архетипът може да подреди тона; той не оправдава обещание, което продуктът не изпълнява.","sources":[]},"exercise":{"type":"scenario","content":{"prompt":"Прототипът има локална форма, но още няма външен получател. Как го описваш?","options":[{"id":"ready","label":"Готова клиентска система, която приема реални заявки."},{"id":"prototype","label":"Учебна страница с локална демонстрация; връзката с получател предстои."},{"id":"hide","label":"Премълчаваме ограничението, за да е по-кратко."}]},"evaluation":{"correct":"prototype"},"feedback":{"explanation":"Текстът показва действително завършената част и следващата проверка."}}},{"module":"s01-m04","lesson":"l04-03","version":7,"base":"silk_road_final_20260924","title":null,"intro":{"body":"Ще развиеш един въпрос в статия с приложима помощ и проверени основания.","outcomes":["Избираш теза и подреждаш подвъпроси.","Даваш пример с ясно обозначени условия.","Разделяш общ съвет и правило на конкретен бизнес."],"deliverable":"План и завършен раздел от полезна статия.","check":"Отговорът не приписва еднакви условия на всички доставчици."},"context_title":"Читателят трябва да може да използва отговора","context":{"body":"Новият учебен случай е „какво да уточня преди изработка на страница“. Материалът може да обясни обхват, текстове, достъп и приемане. Няма основание да пише, че всеки изпълнител включва домейн или постоянна поддръжка.\n\nНаправи списък с пет въпроса и един примерен отговор. При липсващо договорено условие формулирай въпрос към изпълнителя. След прочита човекът трябва да може да сравнява две оферти по еднакви части. AI помага за структурата; източникът и границата на обобщението остават твоя проверка.","sources":[]},"exercise":{"type":"scenario","content":{"prompt":"Само една предоставена оферта включва домейн. Кое изречение е обосновано?","options":[{"id":"all","label":"Всички оферти включват домейн."},{"id":"one","label":"В тази оферта домейнът е включен; при останалите го уточни."},{"id":"ai","label":"Щом AI казва, че е стандартно, го приемаме."}]},"evaluation":{"correct":"one"},"feedback":{"explanation":"Един пример доказва условието на конкретната оферта, а не общо правило."}}},{"module":"s01-m04","lesson":"l04-04","version":7,"base":"silk_road_final_20260924","title":null,"intro":{"body":"Ще напишеш убедително предложение чрез ясна полза, условия и подходящо доказателство.","outcomes":["Разпознаваш несигурността преди действие.","Редактираш фалшива спешност и гаранция.","Сравняваш две формулировки със същите факти."],"deliverable":"Два честни текста и въпроси за проверка на разбирането.","check":"Предложението помага за информиран избор и не измисля наличност."},"context_title":"Мотивът за действие трябва да има основание","context":{"body":"Човек може да отлага, защото не разбира цената, обхвата или какво става след бутона. Това са хипотези, които проверяваме. Нов таймер не отговаря на тези въпроси.\n\nУчебният продукт е наръчник с проверен пример и локална форма. Силната формулировка назовава помощта и ограниченията. За собствената идея направи таблица: колебание, известен факт, нужен отговор. Ако няма истински краен срок или ограничена наличност, не ги добавяй. Сравни вариантите по разбиране преди да търсиш извод за продажби.","sources":[]},"exercise":{"type":"matching","content":{"body":"Свържи твърдението с оценката му.","left":[{"id":"deadline","text":"Проверен срок за заявка до петък."},{"id":"timer","text":"Автоматичен таймер се рестартира всеки ден."},{"id":"limit","text":"Не знаем свободните часове."}],"right":[{"id":"rlimit","text":"Въпрос за уточняване, без обещан недостиг."},{"id":"rtimer","text":"Измислена спешност."},{"id":"rdeadline","text":"Условие, което може да бъде съобщено."}]},"evaluation":{"matches":{"deadline":"rdeadline","timer":"rtimer","limit":"rlimit"}},"feedback":{"explanation":"Примерно решение: Проверен срок за заявка до петък. → Условие, което може да бъде съобщено.; Автоматичен таймер се рестартира всеки ден. → Измислена спешност.; Не знаем свободните часове. → Въпрос за уточняване, без обещан недостиг."}}},{"module":"s01-m04","lesson":"l04-05","version":7,"base":"silk_road_final_20260924","title":null,"intro":{"body":"Ще подготвиш обещаната полезна информация и ще разграничиш различните причини за имейл.","outcomes":["Пазиш връзката между заявка и съдържание.","Даваш едно ясно следващо действие.","Описваш спиране и подходящ показател."],"deliverable":"Примерно писмо и правила за изпращане и отказ.","check":"Работиш с учебните адреси и данни, без да изпращаш реална поредица."},"context_title":"Оставеният адрес има конкретен повод","context":{"body":"В предоставения случай човек иска списък за подготовка. Първото писмо доставя списъка. Не заменяме обещаното с продажба на друга услуга. Потвърждение за запитване, поискан материал и доброволен бюлетин са различни ситуации.\n\nЗа бъдещия си продукт напиши входното събитие, очаквания материал и кога поредицата спира. При отказ или вече решен въпрос проверяваш състоянието преди ново писмо. Самопроверката използва предоставен набор и не изисква пощенска услуга. Реална комуникация се подготвя отделно с допустими получатели и условия.","sources":[]},"exercise":{"type":"matching","content":{"body":"Свържи повода с първото подходящо действие.","left":[{"id":"file","text":"Човек поиска конкретен списък."},{"id":"request","text":"Човек изпрати запитване за час."},{"id":"stop","text":"Човек отказа бюлетина."}],"right":[{"id":"rstop","text":"Спиране на съответната поредица."},{"id":"rrequest","text":"Потвърждение за получено запитване."},{"id":"rfile","text":"Доставяне на обещания списък."}]},"evaluation":{"matches":{"file":"rfile","request":"rrequest","stop":"rstop"}},"feedback":{"explanation":"Примерно решение: Човек поиска конкретен списък. → Доставяне на обещания списък.; Човек изпрати запитване за час. → Потвърждение за получено запитване.; Човек отказа бюлетина. → Спиране на съответната поредица."}}},{"module":"s01-m04","lesson":"l04-06","version":7,"base":"silk_road_final_20260924","title":null,"intro":{"body":"Ще адаптираш един верен материал за различни социални формати.","outcomes":["Избираш въпрос и начало за формата.","Пазиш цената и условията при съкращаване.","Назоваваш желаното действие и проверката."],"deliverable":"Три материала с общи факти и отделна роля.","check":"Различният формат не създава различна оферта."},"context_title":"Една полза, различни начини да я покажеш","context":{"body":"За учебната услуга кратък пост обяснява пакета, карусел подрежда процеса, а видео показва подготовката. Всеки трябва да запази обхвата и условията. Не е нужно да публикуваш в три платформи едновременно, за да упражниш адаптацията.\n\nЗа собствен продукт запиши първия въпрос на читателя, доказателството и действието във всеки вариант. Ако AI съкрати текста, сравни всяко число с основния запис. Наблюдавани реакции могат да насочат към следващ тест; сами не доказват покупка или причината за интереса.","sources":[]},"exercise":{"type":"scenario","content":{"prompt":"При съкращаване срокът „до 7 дни“ става „веднага“. Кой вариант приемаш?","options":[{"id":"short","label":"Оставяме го, защото е по-силно начало."},{"id":"truth","label":"Връщаме точния срок и адаптираме останалия текст."},{"id":"remove","label":"Сменяме числото според платформата."}]},"evaluation":{"correct":"truth"},"feedback":{"explanation":"Форматът се адаптира около фактите; не променя договореното условие."}}},{"module":"s01-m04","lesson":"l04-07","version":7,"base":"silk_road_final_20260924","title":null,"intro":{"body":"Ще свържеш идея, кадри и действие в изпълним кратък видеосценарий.","outcomes":["Избираш конкретен въпрос за зрителя.","Планираш кадър, който показва доказателството.","Проверяваш текст, звук и произход на материала."],"deliverable":"Сценарий от четири до шест кадъра с една основна цел.","check":"Видеото изпълнява началното обещание с наличните ресурси."},"context_title":"Идеята служи на резултата","context":{"body":"За бъдещия продукт сравни три концепции: полезна демонстрация, конкретно сравнение и кратка история за проблем. Избери тази, за която имаш верни факти и изпълними кадри. Архетипът може да даде последователност на историята, но не доказва резултат.\n\nУчебен вариант се прави с телефон, листове и означени данни. За всеки кадър напиши какво разбира зрителят. Причината за споделяне е хипотеза — полезност, разпознаване или изненада — която после проверяваш. „Вирално“ не е условие за завършване и не се обещава предварително.","sources":[]},"exercise":{"type":"scenario","content":{"prompt":"Имаш телефон и точни условия, но няма клиентски кадри. Коя концепция е изпълнима?","options":[{"id":"testimony","label":"Измислен клиент разказва за получен резултат."},{"id":"demo","label":"Означена демонстрация на процеса с наличните материали."},{"id":"viral","label":"Гарантирана виралност с произволен тренд."}]},"evaluation":{"correct":"demo"},"feedback":{"explanation":"Демонстрацията има изпълнимо доказателство. Оригиналността и разпространението се оценяват отделно от истинността."}}},{"module":"s01-m04","lesson":"l04-08","version":7,"base":"silk_road_final_20260924","title":null,"intro":{"body":"Ще опишеш извършена работа и наблюдение, без да им приписваш неизвестен бизнес ефект.","outcomes":["Разделяш ситуация, действие и резултат.","Свързваш твърдение с доказателство.","Посочваш какво още не е измерено."],"deliverable":"Кратък казус и регистър на твърденията.","check":"Учебният тест остава означен като учебен тест."},"context_title":"Казусът показва границата на знанието","context":{"body":"След поправка на учебна форма тестът записва една заявка и разпознава повторението. Можем да покажем версията и протокола. Не знаем как са се променили продажбите. Тази липса не прави работата безполезна; определя точния обхват на твърдението.\n\nЗа собствен продукт запази доказателството за нормален случай и дефект. Опиши как си проверил поправката. Ако има истински клиентски данни, използването и представянето им се уточняват отделно. Синтетична илюстрация не попълва липсващ резултат.","sources":[]},"exercise":{"type":"matching","content":{"body":"Свържи наблюдението с допустимото твърдение.","left":[{"id":"form","text":"Една учебна заявка е записана."},{"id":"sales","text":"Няма предоставени данни за продажби."},{"id":"duplicate","text":"Повторение не добавя нов запис."}],"right":[{"id":"rduplicate","text":"Проверено разпознаване на същата заявка."},{"id":"rsales","text":"Ефектът върху продажбите е неизвестен."},{"id":"rform","text":"Проверено записване в този учебен случай."}]},"evaluation":{"matches":{"form":"rform","sales":"rsales","duplicate":"rduplicate"}},"feedback":{"explanation":"Примерно решение: Една учебна заявка е записана. → Проверено записване в този учебен случай.; Няма предоставени данни за продажби. → Ефектът върху продажбите е неизвестен.; Повторение не добавя нов запис. → Проверено разпознаване на същата заявка."}}},{"module":"s01-m04","lesson":"l04-09","version":7,"base":"silk_road_final_20260924","title":null,"intro":{"body":"Ще превърнеш основен материал в няколко версии и ще пазиш общите факти при обновяване.","outcomes":["Даваш самостоятелна полза на всеки формат.","Следиш източника и версията.","Разпространяваш поправката към зависимите материали."],"deliverable":"Три адаптации и регистър за обновяване.","check":"Променено условие не остава със стара стойност в друг формат."},"context_title":"Версиите имат общ източник","context":{"body":"Основният учебен материал съдържа цена, обхват и срок. От него има пост, имейл и страница. Ако срокът е променен след потвърждение, не е достатъчно да редактираш само най-новия пост.\n\nЗа своя бъдещ продукт направи регистър: източник, версия, зависими материали и отговорник. AI може да предложи адаптации, но сравняваш числата и условията след всяка промяна. При липса на достъп до стара публикация записваш задачата и ограниченията. Съкращаването не бива да превръща условно обещание в безусловно.","sources":[]},"exercise":{"type":"sequence_sort","content":{"items":[{"id":"verify","text":"Провери адресите и отбележи останалите задачи."},{"id":"edit","text":"Поправи достъпните версии."},{"id":"list","text":"Намери зависимите материали."},{"id":"source","text":"Потвърди новото условие в основния запис."}]},"evaluation":{"order":["source","list","edit","verify"]},"feedback":{"explanation":"Промяната започва от потвърден източник и завършва с проверка на разпространените версии."}}},{"module":"s01-m04","lesson":"l04-10","version":7,"base":"silk_road_final_20260924","title":null,"intro":{"body":"Ще сравниш материали според полезното действие и времето за производство.","outcomes":["Избираш показател за конкретната цел.","Смяташ резултат спрямо вложения ресурс.","Планираш тест с ясни ограничения."],"deliverable":"Кратък сравнителен отчет и следваща проверка.","check":"Не заменяш подходящото запитване с общ брой реакции."},"context_title":"Повече съдържание не е автоматично по-добър избор","context":{"body":"Учебен материал А отнема 2 часа и води до 6 подходящи запитвания. Б отнема 4 часа и води до 8. При ограничено време А дава 3 запитвания на час, Б — 2. Това е сметка за предоставените данни, не закон за всички публикации.\n\nЗа своя продукт избери един основен резултат и ресурс. Запиши периода, канала и качеството на запитването. Преди повторение провери дали условията са сравними. Ако липсват истински данни, използвай учебните и отбележи какво ще измериш след публикация.","sources":[]},"exercise":{"type":"calculator","content":{"prompt":"Материал А има 6 подходящи запитвания за 2 часа производство. Колко са на час?","label":"Изчислен резултат","unit":"запитвания/час"},"evaluation":{"value":3},"feedback":{"explanation":"6/2 = 3 подходящи запитвания на час в учебните данни. Това не измерва приходи или причината за разликата."}}},{"module":"s01-m05","lesson":"l05-01","version":6,"base":"silk_road_final_20260924","title":null,"intro":{"body":"Ще подредиш публичното присъствие около едни и същи проверени факти и изпълнимо действие.","outcomes":["Създаваш главен запис на условията.","Избираш профили според аудиторията и капацитета.","Проверяваш адресите и контактите."],"deliverable":"Главен запис, кратко представяне и карта на публичните места.","check":"Посетителят получава еднакви условия във всеки избран канал."},"context_title":"Първи канал за достижим човек","context":{"body":"За нов продукт първо запиши кого искаш да достигнеш и къде имаш основание да го срещнеш. Учебната работилница може да започне със собствена страница и подходящ местен канал. Не е необходимо да поддържа всички мрежи.\n\nГлавният запис съдържа проверени условия и липси. От него се подготвят профилите. При избор сравни човешката нужда, разрешените материали, времето за отговор и достъпа до акаунта. Архетипът подрежда историята, но контактът и фактите трябва да остават ясни. Без собствен акаунт можеш да подготвиш учебните варианти и да провериш последователността им.","sources":[]},"exercise":{"type":"scenario","content":{"prompt":"Имаш два часа седмично и един достъпен местен канал. Как започваш?","options":[{"id":"all","label":"Създаваме профили навсякъде и автоматично копираме текста."},{"id":"focus","label":"Избираме достижим канал, ясен маршрут и време за отговор."},{"id":"followers","label":"Избираме мрежата с най-много потребители независимо от задачата."}]},"evaluation":{"correct":"focus"},"feedback":{"explanation":"Изборът съчетава конкретните хора, достижимостта и капацитета. Броят платформи не доказва присъствие."}}},{"module":"s01-m05","lesson":"l05-02","version":6,"base":"silk_road_final_20260924","title":null,"intro":{"body":"Ще подготвиш полезна Facebook публикация и отговори на конкретни въпроси.","outcomes":["Показваш точните условия в самия материал.","Различаваш въпрос, критика и запитване.","Насочваш към изпълнима следваща стъпка."],"deliverable":"Публикация, три отговора и критерий за резултат.","check":"Наличността се проверява преди да се потвърди час."},"context_title":"Коментарът показва въпрос, не диагноза","context":{"body":"Под учебна публикация човек пита „защо струва толкова?“. Отговорът може да обясни включеното и какво се уточнява допълнително. Не знаем дали човекът е неподходящ клиент или просто сравнява.\n\nЗа бъдещия продукт подготви три реакции: въпрос за цена, неизвестна наличност и оплакване. AI може да предложи чернови, но чувствителният отговор и новото обещание се проверяват от отговорния човек. Не пренасяй лични данни в публичния коментар. Резултатът е ясен отговор и правилно предадено запитване; броят реакции се отчита отделно.","sources":[]},"exercise":{"type":"scenario","content":{"prompt":"Човек пита за свободен час в събота; графикът не е предоставен. Кой отговор е точен?","options":[{"id":"yes","label":"Да, заповядайте, за да не изпуснем клиента."},{"id":"check","label":"Можем да уточним събота след проверка; изпратете предпочитан час по подходящия канал."},{"id":"ignore","label":"Премахваме въпроса."}]},"evaluation":{"correct":"check"},"feedback":{"explanation":"Интересът не създава наличност. Отговорът запазва възможността за разговор без измислено потвърждение."}}},{"module":"s01-m05","lesson":"l05-03","version":6,"base":"silk_road_final_20260924","title":null,"intro":{"body":"Ще свържеш Instagram материалите с една полза и различни въпроси по пътя на избора.","outcomes":["Планираш идея, доказателство и действие.","Пазиш условията в Reel, карусел и Story.","Избираш показател за ролята на материала."],"deliverable":"Мини кампания с три формата и проверими факти.","check":"Творческият стил не скрива цена, обхват или важна граница."},"context_title":"Характер и яснота могат да работят заедно","context":{"body":"Нов продукт може да има последователен визуален характер и да бъде лесен за разбиране. В учебния вариант Reel показва процес, карусел обяснява обхват, Story насочва към условия. Това са избрани роли, не гаранция за алгоритмичен ефект.\n\nЗа собствената идея сравни две палитри и два първи кадъра. Пази текста четим и условията еднакви. Архетипът е творческа посока; реакциите на няколко души са наблюдение, а не доказателство, че цветът причинява покупка. При липса на допустим акаунт предай материалите като учебни файлове.","sources":[]},"exercise":{"type":"matching","content":{"body":"Свържи учебния материал с неговата роля.","left":[{"id":"reel","text":"Кратка демонстрация на процес."},{"id":"carousel","text":"Подреден обхват и условия."},{"id":"story","text":"Ясна връзка към запитване."}],"right":[{"id":"rstory","text":"Дава изпълнима следваща стъпка."},{"id":"rcarousel","text":"Помага за сравнение."},{"id":"rreel","text":"Показва какво се случва."}]},"evaluation":{"matches":{"reel":"rreel","carousel":"rcarousel","story":"rstory"}},"feedback":{"explanation":"Примерно решение: Кратка демонстрация на процес. → Показва какво се случва.; Подреден обхват и условия. → Помага за сравнение.; Ясна връзка към запитване. → Дава изпълнима следваща стъпка."}}},{"module":"s01-m05","lesson":"l05-04","version":6,"base":"silk_road_final_20260924","title":null,"intro":{"body":"Ще направиш кратък TikTok сценарий, който изпълнява обещанието на първия кадър.","outcomes":["Избираш въпрос, начало и видимо доказателство.","Планираш с наличните кадри и права.","Различаваш гледане, споделяне и подходящо действие."],"deliverable":"Сценарий и два варианта на началото с една променлива.","check":"Силен първи кадър не подвежда за резултата или наличността."},"context_title":"Причина за внимание, после доказателство","context":{"body":"Учебният продукт е списък за подготовка преди ремонт. Една идея започва с пропуснат въпрос, друга — с показан пример. И двете трябва да дадат обещаната помощ. „Гледай до края“ без полезен отговор не изпълнява задачата.\n\nЗапиши защо някой би споделил материала: полезност, разпознаване или изненада. Това остава хипотеза. Избери една промяна между версиите и пази останалите условия. Без публикация оценяваш фактите, яснотата и изпълнимостта; не записваш измислени гледания. Реалното разпространение се наблюдава след допустимо публикуване.","sources":[]},"exercise":{"type":"scenario","content":{"prompt":"Две версии се различават по начало, цена, дължина и аудитория. Можеш ли да посочиш ефекта само на първия кадър?","options":[{"id":"yes","label":"Да, победител е версията с повече гледания."},{"id":"no","label":"Не; промените са смесени. Следващият тест изолира една промяна."},{"id":"ai","label":"Да, ако AI избере причината."}]},"evaluation":{"correct":"no"},"feedback":{"explanation":"Няколко едновременни промени не позволяват да отделим конкретния ефект само от общите числа."}}},{"module":"s01-m05","lesson":"l05-05","version":6,"base":"silk_road_final_20260924","title":null,"intro":{"body":"Ще представиш професионално наблюдение с факти, ограничения и смислен въпрос за разговор.","outcomes":["Структурираш кратък казус.","Разделяш промяна в число и причина.","Свързваш публикацията с подходяща аудитория."],"deliverable":"LinkedIn публикация с проверим извод и ясно означени учебни данни.","check":"Казусът не приписва доход или успех, който не е измерен."},"context_title":"Професионалният тон показва основанията","context":{"body":"Учебни данни: от 20 запитвания 12 са подходящи. След промяна на текста има 14, от които 12 са подходящи. Качеството на входа може да се разглежда отделно от броя. Не знаем дали текстът е единствената промяна.\n\nЗа своя бъдещ продукт опиши едно наблюдение, направена работа и следваща проверка. Пиши така, че друг човек да разбере метода и границата му. AI може да редактира стила, но не да добавя клиентски резултат. Означи учебния набор и не го превръщай в история на действителен клиент.","sources":[]},"exercise":{"type":"calculator","content":{"prompt":"В първия учебен период 12 от 20 запитвания са подходящи. Какъв е делът в проценти?","label":"Изчислен резултат","unit":"%"},"evaluation":{"value":60},"feedback":{"explanation":"12/20×100 = 60%. Числото описва дадения период и не обяснява причината."}}},{"module":"s01-m05","lesson":"l05-06","version":6,"base":"silk_road_final_20260924","title":null,"intro":{"body":"Ще свържеш заглавие, миниатюра и видеосъдържание с един конкретен въпрос.","outcomes":["Обещаваш това, което видеото показва.","Подреждаш глави и доказателства.","Измерваш гледането и последващото действие отделно."],"deliverable":"Спецификация за видео с три заглавия и маршрут след гледане.","check":"Зрителят получава отговора, който е избрал от заглавието."},"context_title":"Изборът преди гледане и резултатът след него","context":{"body":"За учебно видео „Какво да уточня преди ремонт“ миниатюрата може да показва списък, а първата глава да назове въпросите. Изображение на резултат, който не е в материала, създава друго очакване.\n\nЗа своя продукт запиши обещанието, първата полезна минута и крайното действие. После избери заглавие и кадър, които съответстват. Гледанията, задържането и получените запитвания отговарят на различни въпроси. При липса на достатъчно данни не обявявай универсална формула за заглавие или цвят на миниатюра.","sources":[]},"exercise":{"type":"matching","content":{"body":"Свържи проверката с въпроса.","left":[{"id":"click","text":"Избор на видеото от заглавие и миниатюра."},{"id":"watch","text":"Продължаване на гледането."},{"id":"action","text":"Получено подходящо запитване."}],"right":[{"id":"raction","text":"Дали следващият маршрут работи?"},{"id":"rwatch","text":"Дали материалът задържа и изпълнява обещанието?"},{"id":"rclick","text":"Дали обещанието насочва подходящ интерес?"}]},"evaluation":{"matches":{"click":"rclick","watch":"rwatch","action":"raction"}},"feedback":{"explanation":"Примерно решение: Избор на видеото от заглавие и миниатюра. → Дали обещанието насочва подходящ интерес?; Продължаване на гледането. → Дали материалът задържа и изпълнява обещанието?; Получено подходящо запитване. → Дали следващият маршрут работи?"}}},{"module":"s01-m05","lesson":"l05-07","version":6,"base":"silk_road_final_20260924","title":null,"intro":{"body":"Ще оцениш рекламен тест по разход, действителни продажби и принос.","outcomes":["Смяташ цена на запитване и придобиване.","Отделяш приход от остатък след разходи.","Задаваш лимит и условие за спиране."],"deliverable":"Учебен рекламен отчет и икономически обосновано решение.","check":"Не е нужен реален рекламен бюджет; всички числа са предоставени."},"context_title":"Платеният тест трябва да може да бъде спрян","context":{"body":"Учебната кампания има 200 евро разход и 10 потвърдени продажби в предоставения набор. Цената за придобиване е 20 евро. Ако приносът преди реклама е 15 евро на продажба, още продажби при същите условия не поправят отрицателната сметка.\n\nЗа бъдещия продукт първо провери обхват, капацитет и допустим разход. Избираш тесен тест с период и критерий. Платформеното приписване на продажба се сравнява с реалния запис. При недостатъчни данни записваш какво още трябва да знаеш. Самопроверката използва учебен набор и не изисква платежна карта.","sources":[]},"exercise":{"type":"calculator","content":{"prompt":"Реклама 200 евро води до 10 учебни продажби. Каква е цената за придобиване на продажба?","label":"Изчислен резултат","unit":"евро"},"evaluation":{"value":20},"feedback":{"explanation":"200/10 = 20 евро. За решение това се сравнява с приноса и останалите условия, не само с прихода."}}},{"module":"s01-m05","lesson":"l05-08","version":6,"base":"silk_road_final_20260924","title":null,"intro":{"body":"Ще определиш полезното участие в общност и предвидимите правила за реакция.","outcomes":["Назоваваш обещание и ритуал за помощ.","Разграничаваш полезен принос и шум.","Планираш модериране според капацитета."],"deliverable":"Месечен план, правила и малък набор показатели.","check":"Измерваш получена помощ и повторно участие, а не само брой коментари."},"context_title":"Причината човек да се върне","context":{"body":"В учебна общност за малки проекти човек може да търси отговор, пример или място за разбор. Полезният ритуал има ясен обхват и кой ще реагира. Без капацитет обещанието „всеки получава лична помощ веднага“ е неизпълнимо.\n\nЗа своя продукт избери един седмичен формат и правило за неподходящо съдържание. Запиши как се обозначават догадки, как се пазят личните данни и как се предава проблем. AI може да подготви обобщение, но не да обяви всеки активен участник за доволен клиент. Полезността се проверява през решен въпрос и ограничение на наблюдението.","sources":[]},"exercise":{"type":"scenario","content":{"prompt":"Има 50 коментара, но 10 въпроса остават без полезен отговор. Какво проверяваш първо?","options":[{"id":"count","label":"Как да увеличим коментарите."},{"id":"help","label":"Ритуала, отговорника и дали въпросите получават приложима помощ."},{"id":"claim","label":"Обявяваме висока удовлетвореност."}]},"evaluation":{"correct":"help"},"feedback":{"explanation":"Активността не доказва изпълнено обещание за помощ. Първо проверяваме конкретната функция на общността."}}},{"module":"s01-m05","lesson":"l05-09","version":6,"base":"silk_road_final_20260924","title":null,"intro":{"body":"Ще подготвиш партньорски материал с ясни факти, творческа свобода и договорени употреби.","outcomes":["Оценяваш съвпадението на аудиторията.","Описваш задължителните факти и забранените твърдения.","Уточняваш прегледа, правата и измерването."],"deliverable":"Задание към създател на съдържание и матрица за приемане.","check":"Лично преживяване не се измисля и права за реклама не се приемат по подразбиране."},"context_title":"Препоръката носи отговорност за смисъла","context":{"body":"Учебен партньор може да покаже демонстрация на новия продукт. Ако не го е използвал, не му даваме сценарий „аз съм доволен клиент“. Материалът назовава действителния произход и партньорството според уточнените условия.\n\nЗа своята идея избери създател по подходяща аудитория, материал и капацитет за преглед. Запиши какво може да редактира, кой проверява фактите и за какви употреби са разрешени файловете. Плащане за публикация не доказва право за всички бъдещи реклами. Приемането включва съдържанието и договорения обхват, а продажбите се измерват отделно.","sources":[]},"exercise":{"type":"matching","content":{"body":"Свържи условието с правилната проверка.","left":[{"id":"experience","text":"Няма действителен опит с продукта."},{"id":"rights","text":"Уточнено е само органично публикуване."},{"id":"facts","text":"Черновата добавя непотвърден срок."}],"right":[{"id":"rfacts","text":"Редакция и проверка при източника."},{"id":"rrights","text":"Отделно договаряне преди платена реклама."},{"id":"rexperience","text":"Означена демонстрация, без измислен отзив."}]},"evaluation":{"matches":{"experience":"rexperience","rights":"rrights","facts":"rfacts"}},"feedback":{"explanation":"Примерно решение: Няма действителен опит с продукта. → Означена демонстрация, без измислен отзив.; Уточнено е само органично публикуване. → Отделно договаряне преди платена реклама.; Черновата добавя непотвърден срок. → Редакция и проверка при източника."}}},{"module":"s01-m05","lesson":"l05-10","version":6,"base":"silk_road_final_20260924","title":null,"intro":{"body":"Ще сравниш два канала по подходящи действия, разход и ограничения на данните.","outcomes":["Използваш правилния знаменател.","Проверяваш качеството след първия клик.","Планираш ограничен следващ тест."],"deliverable":"Сравнителен отчет и аргумент за следващото разпределяне на работа.","check":"Не измисляш приход, когато той липсва в набора."},"context_title":"Каналът трябва да обслужва задачата","context":{"body":"Учебен канал А води до 40 заявки, 20 подходящи. Б води до 25, 20 подходящи. За екип с ограничено време уточняването на неподходящи заявки също има цена. Не знаем приноса и сравнимостта на периодите.\n\nЗа собствен продукт включи в отчета валидност, отговор и крайна стъпка. Броят последователи остава помощно наблюдение. Изборът за следващ тест се прави според целта и капацитета. Ако основната форма не работи, смяната на канала не е първата поправка.","sources":[]},"exercise":{"type":"calculator","content":{"prompt":"Канал Б има 20 подходящи от общо 25 учебни заявки. Какъв е делът в проценти?","label":"Изчислен резултат","unit":"%"},"evaluation":{"value":80},"feedback":{"explanation":"20/25×100 = 80%. Това не доказва по-голям приход или причинен ефект на канала."}}},{"module":"s01-m06","lesson":"l06-01","version":6,"base":"silk_road_final_20260924","title":"Целева страница и ясно предложение","intro":{"body":"Ще подредиш целева страница около едно предложение и действителния път след бутона.","outcomes":["Свързваш началото с конкретно очакване.","Отговаряш на цена, обхват, риск и следваща стъпка.","Проверяваш цялото действие на телефон."],"deliverable":"Структура, текст и тестове за целева страница.","check":"Посетителят разбира дали изпраща въпрос, резервира или плаща."},"context_title":"Несигурността има конкретен въпрос","context":{"body":"За учебен нов продукт човек може да не знае какво включва цената или кой ще отговори. Това се записва като въпрос за проверка, а не като психологическа диагноза. Страницата трябва да показва наличните отговори близо до действието.\n\nНаправи две версии със същите факти: обща похвала и конкретен обхват. Провери разбирането по въпроси, без да насочваш читателя към правилното място. След това тествай формата. По-ясната страница и получената заявка са различни проверки. Само първата не доказва, че бъдещата услуга вече работи.","sources":[]},"exercise":{"type":"scenario","content":{"prompt":"Посетителят не намира какво включва цената, а формата е проверено работеща. Кой е обоснованият първи тест?","options":[{"id":"color","label":"Нова палитра с обещание за повече продажби."},{"id":"scope","label":"По-ясен обхват близо до цената и проверка на разбирането."},{"id":"timer","label":"Таймер без реален краен срок."}]},"evaluation":{"correct":"scope"},"feedback":{"explanation":"Поправката следва наблюдаваната липса. Ефектът върху покупките се проверява отделно."}}},{"module":"s01-m06","lesson":"l06-02","version":6,"base":"silk_road_final_20260924","title":null,"intro":{"body":"Ще определиш минималните данни и надеждното поведение на форма за запитване.","outcomes":["Обосноваваш всяко поле.","Показваш ясно грешка и изчакване.","Проверяваш запис и повторение."],"deliverable":"Спецификация на форма и протокол от учебната лаборатория.","check":"Има един запис за едно действие, а отделният абонамент остава отделен."},"context_title":"Полето и обещанието имат цена за човека","context":{"body":"За запитване за ремонт са нужни контакт и описание на проблема. В учебния случай дата на раждане не помага за това действие. Всяко допълнително поле изисква основание.\n\nВ лабораторията провери нормален вход, липсващ контакт, отказ, забавяне и повторение. Полетата остават при неуспех. Идентификаторът позволява разпознаване на същата заявка. За собствена свързана версия проверяваш и действителния получател и ограничените права. Локалният журнал доказва само учебното поведение в браузъра; не е външна база или доставка на имейл.","sources":[{"label":"Учебна лаборатория","url":"https://imashnujnoto.com/academy-labs/silk-road/"}]},"exercise":{"type":"matching","content":{"body":"Свържи състоянието с очакваното поведение.","left":[{"id":"wait","text":"Изпращането още продължава."},{"id":"fail","text":"Записът не е приет."},{"id":"repeat","text":"Същата заявка е повторена."}],"right":[{"id":"rrepeat","text":"Същият идентификатор, без втори запис."},{"id":"rfail","text":"Ясна грешка и запазени полета."},{"id":"rwait","text":"Видимо изчакване, без потвърден успех."}]},"evaluation":{"matches":{"wait":"rwait","fail":"rfail","repeat":"rrepeat"}},"feedback":{"explanation":"Примерно решение: Изпращането още продължава. → Видимо изчакване, без потвърден успех.; Записът не е приет. → Ясна грешка и запазени полета.; Същата заявка е повторена. → Същият идентификатор, без втори запис."}}},{"module":"s01-m06","lesson":"l06-03","version":6,"base":"silk_road_final_20260924","title":"Цена, обхват и оферта","intro":{"body":"Ще свържеш ясния пакет с реалния разход на изпълнение. Ще провериш какво остава след разходите, преди да определиш цена.","outcomes":["Включваш материали, труд и дадена такса.","Смяташ ефекта на отстъпката.","Отделяш принос от окончателна печалба."],"deliverable":"Калкулация и оферта с обхват и ограничения.","check":"Цената на пакета и предаваното са сравними между вариантите."},"context_title":"Ясният избор не отменя сметката","context":{"body":"Учебна услуга струва 120 евро. Материалите са 32, трудът — 3 часа по 18, дадената платежна такса — 3%. Остатъкът преди постоянни разходи е 30,40 евро. Таксата е учебно условие, а не текуща цена на конкретен доставчик.\n\nЗа бъдещ продукт сравни цена, включено и неизвестни разходи. По-ниската цена може да промени възприетото предложение, но нямаме измерена готовност за плащане. Пакетът трябва да назовава реална разлика. Не добавяй безполезен вариант само за да подтикнеш човека към друг.","sources":[]},"exercise":{"type":"calculator","content":{"prompt":"С дадените учебни числа сметни 120−32−3×18−120×0.03. Използвай десетична точка.","label":"Изчислен резултат","unit":"евро"},"evaluation":{"value":30.4},"feedback":{"explanation":"120−32−54−3.60 = 30.40 евро преди постоянни разходи. Това не е окончателна печалба."}}},{"module":"s01-m06","lesson":"l06-04","version":6,"base":"silk_road_final_20260924","title":"Разговор, предложение и следваща стъпка","intro":{"body":"Ще подредиш разговор и продажбен процес според факти, решения и следваща стъпка.","outcomes":["Уточняваш проблема и условията за изпълнение.","Записваш решение вместо предположен интерес.","Отказваш неподходяща задача ясно."],"deliverable":"Етапи, диагностични въпроси и регистър за проследяване.","check":"Всяко преминаване има наблюдавано основание."},"context_title":"От интерес към уточнена задача","context":{"body":"Човек казва „искам сайт“. Това не уточнява аудитория, съдържание, функция или кой ще го поддържа. За бъдещия си продукт подготви въпроси за резултата и ограниченията, преди да обещаеш срок.\n\nAI може да подреди бележки от разрешени учебни данни. Провери дали не е превърнал въпрос в договорено решение. Регистърът пази известното, неизвестното и следващия отговорник. Учтивият отказ е полезен, когато няма право, капацитет или изпълнимо условие. Не предлагай добавена автоматизация само защото инструментът я позволява.","sources":[]},"exercise":{"type":"sequence_sort","content":{"items":[{"id":"next","text":"Запиши решението и следващата стъпка."},{"id":"offer","text":"Подготви предложение с условия."},{"id":"scope","text":"Провери обхват, права и капацитет."},{"id":"need","text":"Уточни човека, проблема и желания резултат."}]},"evaluation":{"order":["need","scope","offer","next"]},"feedback":{"explanation":"Предложението следва уточнена задача. Интересът сам не е приета оферта."}}},{"module":"s01-m06","lesson":"l06-05","version":6,"base":"silk_road_final_20260924","title":null,"intro":{"body":"Ще избереш доказателство според конкретното колебание пред решението.","outcomes":["Назоваваш твърдението точно.","Проверяваш съвпадението с доказателството.","Редактираш твърдение при липса на основание."],"deliverable":"Карта на четири обещания с проверка и ограничение.","check":"Един тест не се представя като гаранция за цялата услуга."},"context_title":"Доказателството отговаря на определено съмнение","context":{"body":"Учебен прототип има проверен тест за заявка. Това подкрепя конкретното поведение, а не твърдение за всички устройства или непрекъсната наличност. Ако човек пита кой отговаря, снимка на красив интерфейс не дава отговора.\n\nЗа своя бъдещ продукт подреди обещание, въпрос на човека и наличен материал. Демонстрация, описание на процес и действителен отзив имат различен произход. Когато материалът липсва, стесняваш текста или планираш проверка. Не попълваш празното място с генерирано клиентско име.","sources":[]},"exercise":{"type":"scenario","content":{"prompt":"Имаш един успешен учебен тест. Кое твърдение подкрепя той?","options":[{"id":"all","label":"Формата винаги работи без грешка."},{"id":"case","label":"В описания учебен случай заявката е приета и записана."},{"id":"trust","label":"Всички клиенти ни се доверяват."}]},"evaluation":{"correct":"case"},"feedback":{"explanation":"Обхватът на доказателството определя обхвата на твърдението."}}},{"module":"s01-m06","lesson":"l06-06","version":6,"base":"silk_road_final_20260924","title":"Първа полезна стъпка и следваща услуга","intro":{"body":"Ще планираш първата полезна стъпка след покупка и кога допълнителна услуга е подходяща.","outcomes":["Назоваваш получената стойност и отговорника.","Разграничаваш помощ и нова продажба.","Проверяваш реален сигнал за затруднение."],"deliverable":"14-дневен план за въвеждане и условие за подходящо допълнение.","check":"Основното обещание се изпълнява преди разширяване на офертата."},"context_title":"След покупката въпросът се променя","context":{"body":"Новият потребител вече не сравнява само обещания. Той иска да започне и да получи полезния резултат. В учебния случай има достъп до страница, но не разбира първата задача. Предлагането на по-скъп пакет не отстранява тази пречка.\n\nЗа свой продукт запиши първата успешна стъпка, възможния отказ и помощта. Събирай наблюдение преди да тълкуваш липсата на действие като слаб интерес. Допълнение има смисъл, когато основната услуга работи и се появи подходяща следваща нужда. Критерият трябва да може да бъде проверен.","sources":[]},"exercise":{"type":"scenario","content":{"prompt":"Платен клиент не успява да започне заради неясна инструкция. Кое е първото действие?","options":[{"id":"upsell","label":"Предлагаме премиум пакет."},{"id":"help","label":"Уточняваме затруднението, поправяме началото и проверяваме изпълнението."},{"id":"blame","label":"Приемаме, че клиентът не е мотивиран."}]},"evaluation":{"correct":"help"},"feedback":{"explanation":"Първо изпълняваме основното обещание. Причината се проверява по конкретното затруднение."}}},{"module":"s01-m06","lesson":"l06-07","version":6,"base":"silk_road_final_20260924","title":null,"intro":{"body":"Ще напишеш кратък делови имейл с проверено наблюдение и разумна следваща стъпка.","outcomes":["Не приписваш неизвестна причина на проблема.","Даваш нова стойност при последващ контакт.","Задаваш ясни правила за спиране."],"deliverable":"Три примерни писма и правила за преглед и отказ.","check":"Учебната поредица не се изпраща до реални хора като част от упражнението."},"context_title":"Релевантността започва от наблюдението","context":{"body":"Учебният сайт има непълен контакт. Не знаем колко продажби са изгубени. Съобщението може да посочи проверения адрес и конкретната липса, вместо да обещава удвояване на приходите.\n\nЗа собствената услуга подготви първо писмо, полезно продължение и затваряне. Всяко има повод и граница. AI може да предложи чернова от предоставени факти; не получава право да изпраща автоматично. Отказът и вече решената задача са условия за спиране. Реален контакт се подготвя отделно, с допустими данни и приложими правила.","sources":[]},"exercise":{"type":"scenario","content":{"prompt":"В учебния регистър получателят изрично отказва следващи писма. Какво става с поредицата?","options":[{"id":"continue","label":"Продължава, защото следващото писмо е полезно."},{"id":"stop","label":"Спира за този повод и записва отказа."},{"id":"change","label":"Сменяме адреса на подателя и продължаваме."}]},"evaluation":{"correct":"stop"},"feedback":{"explanation":"Правилото за отказ е част от процеса, а не пожелателна бележка."}}},{"module":"s01-m06","lesson":"l06-08","version":6,"base":"silk_road_final_20260924","title":null,"intro":{"body":"Ще провериш дали обещанието за сигурност има действително поведение зад него.","outcomes":["Намираш излишни данни и прекомерен достъп.","Приоритизираш блокиращ риск.","Свързваш публичния текст с извършената проверка."],"deliverable":"Приоритизиран списък, поправен текст и тестове за приемане.","check":"Красив знак или SSL не доказват защита на всички записи."},"context_title":"Доверието следва работата","context":{"body":"Учебният продукт е през HTTPS, но всеки посетител може да прочете чуждите заявки. Шифрованата връзка и правата до данните решават различни задачи. Първият случай не компенсира втория.\n\nЗа собствена идея опиши нужните данни, разрешените хора и начин за проверка. Използвай само тестови записи. Публичният текст трябва да е точен за действително направеното. Не показвай „100% сигурно“. При неподходящ достъп спираш предаването и поправяш правилата, след което повтаряш проверката с различни тестови роли.","sources":[]},"exercise":{"type":"matching","content":{"body":"Свържи проверката с нейния обхват.","left":[{"id":"https","text":"Страницата е достъпна през HTTPS."},{"id":"roles","text":"Чужд посетител не чете чужди заявки."},{"id":"claim","text":"Няма риск при никакви условия."}],"right":[{"id":"rclaim","text":"Неподкрепена абсолютна гаранция."},{"id":"rroles","text":"Проверка на права до записи."},{"id":"rhttps","text":"Защита на връзката."}]},"evaluation":{"matches":{"https":"rhttps","roles":"rroles","claim":"rclaim"}},"feedback":{"explanation":"Примерно решение: Страницата е достъпна през HTTPS. → Защита на връзката.; Чужд посетител не чете чужди заявки. → Проверка на права до записи.; Няма риск при никакви условия. → Неподкрепена абсолютна гаранция."}}},{"module":"s01-m06","lesson":"l06-09","version":6,"base":"silk_road_final_20260924","title":"Плащане и предоставяне на точната услуга","intro":{"body":"Ще разграничиш тестово плащане, получено събитие и предоставено право за точния пакет.","outcomes":["Проверяваш източник, статус и собственик.","Разпознаваш повторено събитие.","Описваш отказ, изчакване и възстановяване."],"deliverable":"Платежна тестова матрица с очаквано състояние на достъпа.","check":"Работиш с предоставени учебни събития; няма реално движение на пари."},"context_title":"Плащане и получена услуга са отделни проверки","context":{"body":"Учебна сесия е pending: още няма предоставен пакет. След потвърдено допустимо събитие paid се предоставя точно договореното право. Повторение на същото събитие не добавя втори пакет. Адресът „Благодарим“ сам не удостоверява статуса.\n\nStripe препоръчва изпълнението да следва проверените сървърни платежни събития. За първото упражнение получаваш означени статуси и очакван резултат, без Stripe акаунт. За собствен допустим sandbox отделно проверяваш връзката, подписа и записите. Учебният успех не е приход и не означава готовност за реална търговия.","sources":[{"label":"Stripe: изпълнение на поръчки","url":"https://docs.stripe.com/checkout/fulfillment?payment-ui=stripe-hosted"}]},"exercise":{"type":"matching","content":{"body":"Свържи учебния статус с очакваното право.","left":[{"id":"pending","text":"Плащането още се изчаква."},{"id":"paid","text":"Потвърдено допустимо плащане за пакет А."},{"id":"repeat","text":"Получено е същото събитие отново."}],"right":[{"id":"rrepeat","text":"Без второ предоставяне."},{"id":"rpaid","text":"Точно едно право за пакет А."},{"id":"rpending","text":"Няма нов платен достъп."}]},"evaluation":{"matches":{"pending":"rpending","paid":"rpaid","repeat":"rrepeat"}},"feedback":{"explanation":"Примерно решение: Плащането още се изчаква. → Няма нов платен достъп.; Потвърдено допустимо плащане за пакет А. → Точно едно право за пакет А.; Получено е същото събитие отново. → Без второ предоставяне."}}},{"module":"s01-m06","lesson":"l06-10","version":6,"base":"silk_road_final_20260924","title":null,"intro":{"body":"Ще съпоставиш аналитика, плащания и предоставен достъп, преди да обявиш резултат.","outcomes":["Назоваваш източника и състоянието на събитието.","Търсиш дубликат, закъснение и липсващ запис.","Избираш опорно число за конкретния въпрос."],"deliverable":"Диагностичен план и критерии за корекция на отчитането.","check":"Повече записани събития не означават повече платили хора."},"context_title":"Човешката стъпка и системният запис","context":{"body":"Учебна аналитика отчита 12 покупки. Платежният журнал има 10 платени сесии; две аналитични събития са повторения. Достъпът трябва да се съпостави с тези сесии и правилните пакети.\n\nЗа свой продукт начертай посещение, избор, плащане и получена услуга. Запиши кое се измерва в браузъра и кое в надеждния регистър. Времевият период и идентификаторът помагат да намериш разликата. Не изтривай записи само за да се изравнят числата; установи причината и проверяваема поправка.","sources":[]},"exercise":{"type":"calculator","content":{"prompt":"Има 12 аналитични събития, от които 2 са повторения. Колко уникални събития остават в учебния набор?","label":"Изчислен резултат","unit":"събития"},"evaluation":{"value":10},"feedback":{"explanation":"12−2 = 10. Това съвпадение още не доказва предоставен достъп; той се проверява отделно."}}},{"module":"s01-m07","lesson":"l07-01","version":6,"base":"silk_road_final_20260924","title":"Домейн, хостинг и собственост на проекта","intro":{"body":"Ще разграничиш адреса, мястото за файловете и връзката между тях, като запазиш собствеността на проекта.","outcomes":["Обясняваш домейн, хостинг и DNS на прост език.","Проверяваш собственик и ограничен достъп.","Тестваш действителния адрес след промяна."],"deliverable":"Регистър на услугите и план за публикуване и връщане.","check":"Не е нужен платен домейн за първата учебна версия."},"context_title":"Безплатна публикация с ясен собственик","context":{"body":"Домейнът е адресът, хостингът доставя файловете, а DNS насочва името към правилното място. За учебна статична страница можеш да използваш предоставения адрес на подходящ безплатен хостинг. Статичната публикация не създава сама база или платежен процес.\n\nЗа бъдещ клиент опиши кой притежава акаунта и файловете, кой има достъп и как се връща проверена версия. Квотите, паузирането и допълнителните услуги се проверяват към датата. Първият локален маршрут остава допустим без външна регистрация. Не прехвърляй зависимост от своя личен акаунт като готова собственост на клиента.","sources":[{"label":"Cloudflare Pages: лимити","url":"https://developers.cloudflare.com/pages/platform/limits/"}]},"exercise":{"type":"matching","content":{"body":"Свържи понятието с ролята.","left":[{"id":"domain","text":"Домейн"},{"id":"hosting","text":"Хостинг"},{"id":"dns","text":"DNS"}],"right":[{"id":"rdns","text":"Насочването на името към услугата."},{"id":"rhosting","text":"Мястото, което обслужва файловете."},{"id":"rdomain","text":"Името на адреса."}]},"evaluation":{"matches":{"domain":"rdomain","hosting":"rhosting","dns":"rdns"}},"feedback":{"explanation":"Примерно решение: Домейн → Името на адреса.; Хостинг → Мястото, което обслужва файловете.; DNS → Насочването на името към услугата."}}},{"module":"s01-m07","lesson":"l07-02","version":6,"base":"silk_road_final_20260924","title":"Избор на инструменти и реален разход","intro":{"body":"Ще избереш малък набор инструменти според задачата, достъпа и поддръжката.","outcomes":["Различаваш необходима функция и удобство.","Проверяваш квота, собственик и възстановяване.","Описваш резервен учебен маршрут."],"deliverable":"Карта на инструментите с разход, права и условие за смяна.","check":"Безплатният прототип не се представя като постоянна услуга без разход."},"context_title":"Изборът започва от работата","context":{"body":"За първата страница трябват файлове и проверен текст. Приемане на заявки добавя данни и права. Жив AI помощник добавя извиквания към модел и други лимити. Това са различни потребности.\n\nЗа собствен продукт запиши функцията, минималния избор, квотата и кой отговаря при отказ. GitHub и подходящ хостинг могат да поддържат учебния старт; Supabase Free е възможна отделна учебна база при допустим акаунт. Планът и паузирането се проверяват. Абонамент за чат не е включено API потребление. Не купувай услуга само защото присъства в чужд списък.","sources":[{"label":"Supabase: планове","url":"https://supabase.com/pricing"}]},"exercise":{"type":"scenario","content":{"prompt":"Статична учебна страница използва предварително проверен текст. Нужно ли е AI API извикване при всяко посещение?","options":[{"id":"yes","label":"Да, защото е създадена с AI."},{"id":"no","label":"Не за този обхват; жив AI помощник би бил отделна функция и сметка."},{"id":"all","label":"Всички функции са без разход завинаги."}]},"evaluation":{"correct":"no"},"feedback":{"explanation":"Помощта при изработка и вграденият AI за крайни потребители са различни употреби."}}},{"module":"s01-m07","lesson":"l07-03","version":6,"base":"silk_road_final_20260924","title":"Защитена връзка, архив и проверено възстановяване","intro":{"body":"Ще подготвиш проверка за наличност и възстановяване, а не само отметка за архив.","outcomes":["Разделяш HTTPS, архив и наблюдение.","Проверяваш възстановената версия.","Назоваваш отговорник при сигнал."],"deliverable":"План за архив, тестово възстановяване и реакция при отказ.","check":"Съществуващ файл не се приема за проверен възстановим проект."},"context_title":"Поддръжката е част от бъдещия продукт","context":{"body":"Учебният хостинг пази работеща страница, но базата е паузирана. Наблюдението само на началния адрес пропуска неработещата заявка. Затова проверката включва важната функция и получателя.\n\nЗа собствена идея опиши какви файлове и данни се архивират, как се възстановяват в разрешена тестова среда и кой реагира. Не включвай тайни в общ документ. Използвай измислени записи. След възстановяване изпълни нормален случай, грешка и повторение. Точният план за архивиране и разход зависи от избраната услуга и се проверява преди клиентско предаване.","sources":[]},"exercise":{"type":"sequence_sort","content":{"items":[{"id":"record","text":"Запиши резултата и отговорника."},{"id":"test","text":"Провери ключовата функция и записите."},{"id":"restore","text":"Възстанови в разрешена тестова среда."},{"id":"scope","text":"Определи файловете и данните за възстановяване."}]},"evaluation":{"order":["scope","restore","test","record"]},"feedback":{"explanation":"Архивът се приема след проверено възстановяване, а не само след създаване на файл."}}},{"module":"s01-m07","lesson":"l07-04","version":6,"base":"silk_road_final_20260924","title":"Начало на клиентски проект и предаване","intro":{"body":"Ще превърнеш началото на клиентски проект в ясни решения, материали и права.","outcomes":["Уточняваш обхват, отговорници и приемане.","Искаш ограничен достъп за конкретна задача.","Пазиш неизвестното като въпрос."],"deliverable":"Начален пакет за проект и списък за предаване.","check":"Чужд документ не променя договорени условия без потвърждение."},"context_title":"Кой взема решението и кой проверява","context":{"body":"Учебен клиент дава описание на услуга и иска „всичко автоматично“. Преди изграждане уточняваш кои действия са разрешени, кои данни са налични и кой потвърждава цена или час.\n\nЗа бъдещ продукт подготви кратко задание, регистър на материали и проверки за приемане. Достъпът се дава за задача, не чрез обща парола за всички. AI може да обобщи бележките, но сравняваш всяко решение с източника. Предаването включва собственост, проверена версия, ограничения и следващ отговорник.","sources":[]},"exercise":{"type":"scenario","content":{"prompt":"В бележка пише „вероятно ще добавим плащания“, а AI я обобщава като договорена функция. Какво следва?","options":[{"id":"build","label":"Добавяме я без уточнение."},{"id":"verify","label":"Връщаме я като отворен въпрос и потвърждаваме обхвата."},{"id":"promise","label":"Обещаваме срок, за да не бавим проекта."}]},"evaluation":{"correct":"verify"},"feedback":{"explanation":"Предположение не става прието решение чрез обобщаване."}}},{"module":"s01-m08","lesson":"l08-01","version":6,"base":"silk_road_final_20260924","title":null,"intro":{"body":"Ще подредиш важните данни, акаунти и отговорници на малък проект.","outcomes":["Определяш какво пазиш и от кого зависи.","Ограничаваш правата според действието.","Планираш възстановяване без единствен човек."],"deliverable":"Регистър на активите и първи приоритети за защита.","check":"Общият документ не съдържа пароли, тайни или реални клиентски записи."},"context_title":"Правото да виждаш не е право да променяш","context":{"body":"Учебен помощник трябва да обобщи пет измислени заявки. Това не изисква администраторски ключ или право да изтрива. За всяка връзка описваш нужната информация и разрешеното действие.\n\nЗа бъдещия продукт запиши собственик, достъп и възстановяване. Ако използваш AI, провери кои данни могат да бъдат предоставени и кой одобрява действие. Публичен ключ и ограничени правила се проверяват заедно. Secret или service_role ключ не се поставя в страницата. Първата практика използва предоставени данни и не изисква достъп до чужда система.","sources":[{"label":"Supabase: защита на Data API","url":"https://supabase.com/docs/guides/api/securing-your-api"}]},"exercise":{"type":"scenario","content":{"prompt":"Помощникът трябва само да обобщи учебни заявки. Какви права са подходящи?","options":[{"id":"admin","label":"Пълен администраторски достъп за удобство."},{"id":"read","label":"Ограничено четене на разрешения набор, без изтриване и изпращане."},{"id":"secret","label":"Поставяме тайния ключ в публичната страница."}]},"evaluation":{"correct":"read"},"feedback":{"explanation":"Правата следват конкретната задача. Удобството не е основание за административен достъп."}}},{"module":"s01-m08","lesson":"l08-02","version":6,"base":"silk_road_final_20260924","title":"Пароли, втори фактор и управление на достъп","intro":{"body":"Ще подредиш входа и правата така, че достъпът да може да бъде ограничаван и възстановяван.","outcomes":["Използваш отделни идентичности и уникални пароли.","Различаваш втори фактор и право до конкретен ресурс.","Описваш даване, преглед и отнемане на достъп."],"deliverable":"Матрица на достъпа и план за възстановяване без тайни в документа.","check":"Входът на човек не дава автоматично право да вижда всеки запис."},"context_title":"Кой може да направи точно това","context":{"body":"В учебния проект двама души имат различни задачи: единият проверява заявки, другият редактира публичен текст. Общата администраторска парола скрива разликата и затруднява отнемането на права.\n\nПодготви отделни роли и проверка при напускане или смяна на задача. Вторият фактор помага за входа; правилата за ресурса определят какво може да се вижда и променя. Не записвай пароли или кодове в портфолиото. За първата задача работиш с матрица и измислени роли, без истински акаунти.","sources":[]},"exercise":{"type":"matching","content":{"body":"Свържи мярката с ролята.","left":[{"id":"login","text":"Втори фактор при вход."},{"id":"scope","text":"Право само за редакция на публичен текст."},{"id":"leave","text":"Човек напуска проекта."}],"right":[{"id":"rleave","text":"Преглед и отнемане на ненужния достъп."},{"id":"rscope","text":"Ограничение на позволеното действие."},{"id":"rlogin","text":"Допълнителна проверка на входа."}]},"evaluation":{"matches":{"login":"rlogin","scope":"rscope","leave":"rleave"}},"feedback":{"explanation":"Примерно решение: Втори фактор при вход. → Допълнителна проверка на входа.; Право само за редакция на публичен текст. → Ограничение на позволеното действие.; Човек напуска проекта. → Преглед и отнемане на ненужния достъп."}}},{"module":"s01-m08","lesson":"l08-03","version":6,"base":"silk_road_final_20260924","title":"Подозрителни съобщения и социално инженерство","intro":{"body":"Ще провериш подозрително искане по независим канал преди достъп, изпращане или плащане.","outcomes":["Разпознаваш натиск и подмяна на източника.","Отделяш чужд текст от разрешение за действие.","Записваш проверения резултат."],"deliverable":"Протокол за проверка на учебно подозрително съобщение.","check":"Добрият правопис и познатото име не доказват произход."},"context_title":"Спешността не дава право","context":{"body":"Учебен имейл твърди, че домейнът изтича и иска незабавно плащане през нов адрес. Проверяваш чрез познатия регистратор или предварително известен контакт, а не чрез връзката в съобщението.\n\nСъщият принцип важи за текст в файл към AI: „изпрати контактите“ не променя разрешените права. Разделителите в заданието помагат за четене, но не са техническа защита. За бъдещия продукт създай правило за независима проверка и ограничени действия. Учебният случай използва измислени данни; не тествай непознати реални адреси или получатели.","sources":[]},"exercise":{"type":"scenario","content":{"prompt":"Познато име иска спешен превод към нова сметка. Какво правиш първо?","options":[{"id":"pay","label":"Плащаме, защото името е познато."},{"id":"independent","label":"Проверяваме искането през предварително известен независим канал."},{"id":"reply","label":"Питаме само чрез отговор на подозрителния имейл."}]},"evaluation":{"correct":"independent"},"feedback":{"explanation":"Същият компрометиран канал може да повтори искането. Нужен е независимо установен източник."}}},{"module":"s01-m08","lesson":"l08-04","version":6,"base":"silk_road_final_20260924","title":null,"intro":{"body":"Ще подготвиш първа реакция при инцидент с роли, факти и проверено възстановяване.","outcomes":["Спираш засегнатото действие според случая.","Пазиш журнал и известни факти.","Проверяваш поправката преди възобновяване."],"deliverable":"План за учебен инцидент с комуникация и приемане.","check":"Не изтриваш историята и не обещаваш причина преди проверката."},"context_title":"Когато автоматизацията направи грешка","context":{"body":"Учебен процес изпраща повторно известие за една заявка. Спираш засегнатата поредица, запазваш идентификаторите и установяваш обхвата. Не продължаваш само защото следващият опит изглежда нормален.\n\nЗа бъдещ продукт опиши кой координира, кой има технически права и кой информира засегнатите. Причината, поправката и възстановяването се документират отделно. Първият тест след поправка включва повторение и отказ. При действителен инцидент конкретните уведомявания и срокове се определят по приложимите условия, не от учебния пример.","sources":[]},"exercise":{"type":"sequence_sort","content":{"items":[{"id":"resume","text":"Възобнови след проверка и запиши отговорника."},{"id":"fix","text":"Поправи и изпитай грешката и повторението."},{"id":"facts","text":"Запази фактите и установи обхвата."},{"id":"stop","text":"Ограничи засегнатия процес."}]},"evaluation":{"order":["stop","facts","fix","resume"]},"feedback":{"explanation":"Възстановяването следва доказана поправка. Журналът не се премахва, за да изглежда случаят решен."}}},{"module":"s01-m09","lesson":"l09-01","version":5,"base":"silk_road_final_20260924","title":"GA4 и проверка на изпълненото действие","intro":{"body":"Ще подготвиш измерване, което следи изпълнена задача и се сверява с реалния запис.","outcomes":["Назоваваш събитие и очаквано действие.","Проверяваш дубликат и липсващ запис.","Свързваш отчета с въпрос за решение."],"deliverable":"План за измерване и протокол от учебни събития.","check":"Можеш да упражниш логиката с предоставен набор без GA4 акаунт."},"context_title":"Измервай какво действително е завършено","context":{"body":"В учебния набор има 30 отваряния на форма, 12 натискания и 9 получени валидни заявки. Всяко число назовава различно действие. Подходящото основно събитие зависи от целта, а не от това кое е най-лесно за отчитане.\n\nЗа бъдещия продукт запиши събитието, идентификатора, източника и периода. Сравни браузърния сигнал с разрешения регистър. Ако измерването липсва или е ограничено, отбележи това. Тестовият набор не доказва поведението на всички посетители. Използвай минимални учебни данни и не поставяй лични контакти в аналитични полета.","sources":[]},"exercise":{"type":"calculator","content":{"prompt":"В учебния набор 9 валидни заявки следват 30 отваряния на формата. Какъв е делът в проценти?","label":"Изчислен резултат","unit":"%"},"evaluation":{"value":30},"feedback":{"explanation":"9/30×100 = 30%. Това е отношение между посочените събития, не доказана причина за отпадане."}}},{"module":"s01-m09","lesson":"l09-02","version":5,"base":"silk_road_final_20260924","title":"Показатели, които помагат за решение","intro":{"body":"Ще избереш малко показатели, които могат да променят конкретно решение.","outcomes":["Свързваш показател с цел и отговорник.","Смяташ правилна единица и знаменател.","Включваш качество и капацитет."],"deliverable":"Табло с показатели, източници и условия за действие.","check":"Брой посещения не замества използваемия резултат."},"context_title":"Числото трябва да води до въпрос","context":{"body":"Учебният продукт има 100 посещения и 8 валидни заявки. Екипът отговаря в договорения срок на 6. Ако целта е навременен отговор, 6/8 е полезно отношение; 6/100 отговаря на друг въпрос.\n\nЗа собствена идея избери до три начални показателя: изпълнено действие, качество и разход или време. Запиши откъде идват и кой реагира. При промяна на дефиницията започва ново сравнение. Не избирай число само защото расте или изглежда добре в отчет.","sources":[]},"exercise":{"type":"calculator","content":{"prompt":"От 8 валидни заявки на 6 е отговорено в срок. Какъв е делът на навременните отговори в проценти?","label":"Изчислен резултат","unit":"%"},"evaluation":{"value":75},"feedback":{"explanation":"6/8×100 = 75%. Знаменателят са валидните заявки, защото проверяваме отговора след тях."}}},{"module":"s01-m09","lesson":"l09-03","version":5,"base":"silk_road_final_20260924","title":"От наблюдение към проверено решение","intro":{"body":"Ще различиш наблюдение, хипотеза и проверка преди да обясниш причината за промяна.","outcomes":["Пазиш фактите отделно от интерпретацията.","Търсиш други променени условия.","Избираш малък тест с критерий."],"deliverable":"Диагностична карта и обоснована следваща проверка.","check":"Малък набор или две различни седмици не доказват причинност."},"context_title":"Хората не се обясняват само с две числа","context":{"body":"След нов текст учебните заявки стават от 10 на 14. Същевременно има реклама и различен сезон. Наблюдението е вярно за дадения набор, но причината не е отделена. Не заключавай, че цветът или архетипът е продал повече.\n\nЗа бъдещия продукт запиши всички известни промени и липси. Избери един въпрос за следващ тест и една променлива, когато е изпълнимо. При малко случаи полезният резултат може да е открит дефект или по-добре формулирана хипотеза. Не е нужно да обявиш победител.","sources":[]},"exercise":{"type":"matching","content":{"body":"Разграничи трите изречения.","left":[{"id":"fact","text":"В набора има 14 вместо 10 заявки."},{"id":"idea","text":"Възможно е по-ясният текст да помага."},{"id":"limit","text":"Рекламата и сезонът също са променени."}],"right":[{"id":"rlimit","text":"Ограничение на причинния извод."},{"id":"ridea","text":"Хипотеза."},{"id":"rfact","text":"Наблюдение."}]},"evaluation":{"matches":{"fact":"rfact","idea":"ridea","limit":"rlimit"}},"feedback":{"explanation":"Примерно решение: В набора има 14 вместо 10 заявки. → Наблюдение.; Възможно е по-ясният текст да помага. → Хипотеза.; Рекламата и сезонът също са променени. → Ограничение на причинния извод."}}},{"module":"s01-m09","lesson":"l09-04","version":5,"base":"silk_road_final_20260924","title":null,"intro":{"body":"Ще подготвиш кратък отчет за резултат, разход, ограничения и следващи решения.","outcomes":["Пишеш първата страница около нуждата на читателя.","Показваш източник и сравним период.","Назоваваш решение и отговорник."],"deliverable":"Месечен отчет с конкретни следващи действия.","check":"Не скриваш липси зад красиви графики."},"context_title":"Отчетът е инструмент за следващата работа","context":{"body":"Учебният собственик иска да знае защо заявките чакат. Първата страница показва получените заявки, отговорите в срок и проверката на процеса. Декоративна графика на последователи не отговаря на въпроса.\n\nЗа собствен продукт подготви факт, ограничение, решение и отговорник. Приложи подробните данни отделно. AI може да обобщи предоставената таблица, но проверяваш числата и дали не е добавил причина. Завърши с една проверима задача, срок и условие за приемане.","sources":[]},"exercise":{"type":"scenario","content":{"prompt":"Отчетът има графики, но няма следващо решение или отговорник. Какво добавяш първо?","options":[{"id":"charts","label":"Още графики."},{"id":"decision","label":"Конкретна проверка, отговорник и критерий за приемане."},{"id":"claim","label":"Общо твърдение, че всичко расте."}]},"evaluation":{"correct":"decision"},"feedback":{"explanation":"Отчетът става полезен, когато показва какво ще се направи и как ще се провери."}}},{"module":"s01-m10","lesson":"l10-01","version":6,"base":"silk_road_practical_review_20260925","title":"Имейл поредици с правила за начало и спиране","intro":{"body":"Ще подготвиш имейл поредица с ясно начало, спиране и предаване към човек.","outcomes":["Свързваш писмото с допустимо входно събитие.","Проверяваш отказ и вече решен въпрос.","Пазиш идентификатор и отговорник."],"deliverable":"Три примерни писма, таблица на състоянията и тестове за изход.","check":"Поредицата се изпитва с предоставени данни, без реално изпращане."},"context_title":"Автоматичното действие има условие","context":{"body":"Учебно запитване получава потвърждение. После човек отказва следваща комуникация по този повод. Поредицата трябва да спре, независимо че писмото е било планирано по-рано. Повторен вход не създава втора еднаква поредица.\n\nЗа бъдещия продукт запиши входното събитие, нужните данни, състоянието и изходните правила. Включи липсващ контакт, отказ и повторение. AI може да предложи текст, но условието за изпращане се проверява в процеса. Подходяща външна връзка е следваща задача за допустим акаунт, а не изискване за първото упражнение.","sources":[]},"exercise":{"type":"sequence_sort","content":{"items":[{"id":"log","text":"Запиши резултата или предай грешката към отговорник."},{"id":"action","text":"Изпълни разрешеното действие само веднъж."},{"id":"state","text":"Провери адрес, отказ и текущо състояние."},{"id":"input","text":"Получено е допустимо входно събитие."}]},"evaluation":{"order":["input","state","action","log"]},"feedback":{"explanation":"Проверка на текущото състояние предхожда изпращането. Предишният план не отменя по-нов отказ."}}},{"module":"s01-m10","lesson":"l10-02","version":5,"base":"silk_road_final_20260924","title":"Чернови, одобрение и публикуване","intro":{"body":"Ще разделиш чернова, преглед и публикация с ясни права и възможност за спиране.","outcomes":["Даваш на материала проверимо състояние.","Ограничаваш чувствителния отговор и обещание.","Проверяваш резултата след прекъсване."],"deliverable":"Схема за подготовка, одобрение, публикуване и журнал.","check":"Готов текст от AI не получава автоматично право за публикация."},"context_title":"Агентът не става собственик на решението","context":{"body":"Учебният агент подготвя пост с цена. Източникът е актуален, но материалът още няма преглед. Той остава чернова. При публикация и прекъсване първо се проверява действителният статус, за да не се изпрати втори път.\n\nЗа собствен продукт опиши позволените инструменти и действия. Връзка през MCP може да даде достъп до функция в подходящ клиент; това не доказва наличност във всеки план и не разрешава всяко действие. Първата практика използва състояния и предоставени записи. Реална интеграция се изпитва отделно с ограничени права и начин за спиране.","sources":[{"label":"MCP: архитектура и роли","url":"https://modelcontextprotocol.io/docs/learn/architecture"}]},"exercise":{"type":"matching","content":{"body":"Свържи състоянието с допустимото действие.","left":[{"id":"draft","text":"AI е подготвил непроверен текст с цена."},{"id":"unclear","text":"Публикацията е прекъснала без потвърждение."},{"id":"complaint","text":"Има чувствително клиентско оплакване."}],"right":[{"id":"rcomplaint","text":"Предаване към определения човек."},{"id":"runclear","text":"Проверка на действителния статус преди повторение."},{"id":"rdraft","text":"Остава чернова за преглед."}]},"evaluation":{"matches":{"draft":"rdraft","unclear":"runclear","complaint":"rcomplaint"}},"feedback":{"explanation":"Примерно решение: AI е подготвил непроверен текст с цена. → Остава чернова за преглед.; Публикацията е прекъснала без потвърждение. → Проверка на действителния статус преди повторение.; Има чувствително клиентско оплакване. → Предаване към определения човек."}}},{"module":"s01-m10","lesson":"l10-03","version":5,"base":"silk_road_final_20260924","title":"Приемане и проследяване на заявки","intro":{"body":"Ще проследиш една заявка от входа до правилния човек и крайното състояние.","outcomes":["Пазиш идентификатор, нужни данни и статус.","Разпознаваш повторение и различен проект.","Проверяваш разпределяне, отговор и отказ."],"deliverable":"Процес и тестова матрица за приемане и проследяване на заявки.","check":"Изпратено известие не е същото като надежден регистър."},"context_title":"Една заявка, проследена през връзките","context":{"body":"В лабораторията страницата приема измислен вход и го записва в локален журнал. Нормален случай, грешка и повторение се виждат отделно. Това е действително изпълнена учебна връзка в браузъра, но още не е сървърна база.\n\nЗа собствена допустима интеграция добавяш разрешен получател, ограничени права и проверка на записа. Две различни задачи на един човек не се сливат само заради общ имейл. Повторението на една задача се разпознава по нейния идентификатор. Неуспешното известие се проследява, а заявката остава в регистъра.","sources":[{"label":"Учебна лаборатория","url":"https://imashnujnoto.com/academy-labs/silk-road/"}]},"exercise":{"type":"scenario","content":{"prompt":"Същият идентификатор и данни пристигат повторно. Какво трябва да стане?","options":[{"id":"new","label":"Създаваме нова заявка за всеки вход."},{"id":"same","label":"Връщаме същия резултат без втори запис."},{"id":"delete","label":"Изтриваме първия запис."}]},"evaluation":{"correct":"same"},"feedback":{"explanation":"Повторението на едно действие не е нов проект. При различни данни със същия идентификатор проверяваме конфликт."}}},{"module":"s01-m10","lesson":"l10-04","version":5,"base":"silk_road_final_20260924","title":"Малка автоматизация: проверка и общ разход","intro":{"body":"Ще оцениш малка автоматизация по качество, откази и общо спестено време.","outcomes":["Описваш ръчния процес преди свързване.","Изпитваш непълни данни и чужда инструкция.","Включваш преглед, поправки и поддръжка в сметката."],"deliverable":"План за пилот с тестове, сметка и условие за спиране.","check":"Бързата чернова не се приема като завършена автоматизация."},"context_title":"Полезната автоматизация намалява общата работа","context":{"body":"Учебен процес ръчно отнема 100 минути. С AI подготовката е 20, прегледът 40 и поправките 15. Общото е 75, спестени са 25 минути. Ако прегледът или отказите са пропуснати, сметката е непълна.\n\nЗа бъдещ продукт започни с ограничен пилот и измислени данни. Провери нормален вход, липсващ факт, противоречие, повторение и опит за чуждо указание. MCP е възможен начин за връзка при подходящи права; не замества правилата и не е необходим за началния маршрут. Разширяване следва проверено качество и капацитет.","sources":[]},"exercise":{"type":"calculator","content":{"prompt":"Ръчно: 100 минути. С AI: 20 подготовка + 40 преглед + 15 поправки. Колко минути са спестени?","label":"Изчислен резултат","unit":"минути"},"evaluation":{"value":25},"feedback":{"explanation":"100−(20+40+15) = 25 минути. Други разходи и поддръжка се включват отделно."}}},{"module":"s01-m11","lesson":"l11-01","version":5,"base":"silk_road_final_20260924","title":null,"intro":{"body":"Ще опишеш малка услуга или продукт чрез конкретен проблем, предаван резултат и проверима икономика.","outcomes":["Назоваваш човек, нужда и сегашна алтернатива.","Разделяш предаденото от очаквания бизнес ефект.","Смяташ разходите и допусканията."],"deliverable":"Едностраничен бизнес модел с условия за ограничен пилот.","check":"Не приписваш готовност за плащане без действителни данни."},"context_title":"Кой има причина да избере това","context":{"body":"За нов продукт алтернативата може да е човекът да направи задачата сам, да я отложи или да избере друга услуга. Трябва да знаем какво затруднение решаваме и какъв проверен резултат предаваме.\n\nУчебната оферта е страница за една услуга с проверена форма. Това не гарантира клиенти или продажби. За собствена идея запиши проблем, обхват, разход и липсващо допускане. Малкият пилот проверява изпълнението и полезността в ограничени условия. Не обявявай всички хора за готови да платят само защото прототипът изглежда добре.","sources":[]},"exercise":{"type":"matching","content":{"body":"Свържи твърдението с неговия вид.","left":[{"id":"deliver","text":"Предаваме проверена страница и форма."},{"id":"effect","text":"Клиентът ще получи повече продажби."},{"id":"assume","text":"Тази аудитория би платила предложената цена."}],"right":[{"id":"rassume","text":"Допускане, ако няма данни."},{"id":"reffect","text":"Бизнес ефект за отделна проверка."},{"id":"rdeliver","text":"Резултат в обхвата на изпълнението."}]},"evaluation":{"matches":{"deliver":"rdeliver","effect":"reffect","assume":"rassume"}},"feedback":{"explanation":"Примерно решение: Предаваме проверена страница и форма. → Резултат в обхвата на изпълнението.; Клиентът ще получи повече продажби. → Бизнес ефект за отделна проверка.; Тази аудитория би платила предложената цена. → Допускане, ако няма данни."}}},{"module":"s01-m11","lesson":"l11-02","version":5,"base":"silk_road_final_20260924","title":null,"intro":{"body":"Ще подготвиш процес за намиране на подходящи клиенти с видим повод и следваща стъпка.","outcomes":["Търсиш конкретна нужда и право за решение.","Подготвяш разговор от проверено наблюдение.","Измерваш преминаването между етапите."],"deliverable":"Четириседмичен план и регистър на контактите и решенията.","check":"AI не създава клиентска история или разрешение за изпращане."},"context_title":"Подходящият разговор има основание","context":{"body":"Учебен магазин подготвя каталог и няма последователни продуктови снимки. Това е повод да се уточнят материалите, обхватът и условията. Не знаем бюджета или причината за липсата.\n\nЗа бъдещата услуга подготви пет въпроса и малка следваща стъпка. Разграничи отговор, разговор, оферта и приета работа. AI може да подреди разрешените бележки, но не получава автоматично право за масово изпращане. Използвай учебния регистър за първата сметка. Истински контакти и резултати се записват само когато са действително получени.","sources":[]},"exercise":{"type":"calculator","content":{"prompt":"Учебният регистър има 12 отговора и 6 проведени разговора. Какъв е делът на разговорите спрямо отговорите в проценти?","label":"Изчислен резултат","unit":"%"},"evaluation":{"value":50},"feedback":{"explanation":"6/12×100 = 50%. Това не е дял на клиенти и не прогнозира бъдещ доход."}}},{"module":"s01-m11","lesson":"l11-03","version":5,"base":"silk_road_final_20260924","title":null,"intro":{"body":"Ще направиш оферта, която плаща действителната работа и описва приемането и промяната на обхват.","outcomes":["Включваш подготовка, проверка и предаване.","Смяташ цена с дадени разходи и такси.","Договаряш допълнителна работа преди изпълнение."],"deliverable":"Оферта с калкулация, редакции и процедура за промяна.","check":"Отстъпка и разширение се оценяват по сметката, а не само по желание за продажба."},"context_title":"Клиентът купува приет резултат","context":{"body":"Учебната задача има 100 AI чернови, от които 80 са приети след проверка. Разходът за процеса е 160 евро. Цената на приет резултат е 2 евро, а не 1,60. Това е учебна сметка с предоставен обхват.\n\nЗа собствен продукт раздели настройката, изпълнението и поддръжката. Краткото време за генериране не премахва проверката, правата и координацията. Ако клиентът поиска нова функция, оцени променения обхват преди обещание. Не обосновавай цена с измислен бъдещ доход на клиента.","sources":[]},"exercise":{"type":"calculator","content":{"prompt":"Учебният процес струва 160 евро и има 80 приети резултата. Каква е цената на приет резултат?","label":"Изчислен резултат","unit":"евро/резултат"},"evaluation":{"value":2},"feedback":{"explanation":"160/80 = 2 евро. Знаменателят са приетите резултати, а не всички създадени чернови."}}},{"module":"s01-m11","lesson":"l11-04","version":2,"base":"silk_road_practical_review_20260925","title":null,"intro":{"body":"Ще събереш работата от курса в изпълним план и ще провериш готовността за предаване.","outcomes":["Свързваш проблем, предложение, страница и получено действие.","Проверяваш разход, капацитет и откази.","Подреждаш следващи 30, 60 и 90 дни."],"deliverable":"Проектна папка, протокол за приемане и план с ясни ограничения.","check":"Отделяш учебен случай, проверен прототип и действително публикувана услуга."},"context_title":"Завършеният проект има доказателства и граници","context":{"body":"Финалът свързва твоето описание на проблема, верни условия, страница, действие, права, измерване и сметка. За всяка част посочи проверената версия и резултата. Ако връзката е само локална, го означи.\n\nИзпълни нормален случай, липсващо поле, отказ, забавяне, повторение и неподходящ достъп в допустимата учебна среда. Критичен дефект отлага клиентското предаване. Подреди какво ще провериш през следващите 30 дни; разширяване следва устойчиво изпълнение. Завършването на курса отчита учебната работа и не гарантира позиция, доход или пазарен успех.","sources":[]},"exercise":{"type":"scenario","content":{"prompt":"Проектът има красив сайт, но повторено плащане предоставя два пакета и липсва проверка на чужд достъп. Готов ли е за реални клиенти?","options":[{"id":"ready","label":"Да, ако първата покупка работи."},{"id":"hold","label":"Предаването се отлага; поправяме критичните случаи и повтаряме протокола."},{"id":"hide","label":"Да, като премахнем тези случаи от отчета."}]},"evaluation":{"correct":"hold"},"feedback":{"explanation":"Готовността следва критериите за приемане. Критичният дефект не се компенсира от дизайн или успешно преминат отделен случай."}}}]$curriculum$::jsonb;
 release_name text := 'silk_road_full_20261003';
 spec jsonb;
 l public.academy_lessons;
 v public.academy_lesson_versions;
 old_ids uuid[];
 before_image jsonb;
 preserved jsonb;
 after_preserved jsonb;
 intro_id uuid;
 practice_id uuid;
 context_position integer;
 practice_position integer;
 eligible integer;
 already_applied integer;
 initial_progress text;
 initial_attempts text;
 result jsonb;
BEGIN
 LOCK TABLE public.academy_lessons,public.academy_lesson_versions,
   public.academy_lesson_blocks,academy_private.lesson_block_keys,
   public.academy_lesson_progress,public.academy_lesson_attempts_v2
   IN SHARE ROW EXCLUSIVE MODE;
 SELECT count(*) INTO already_applied FROM public.academy_lessons a
 JOIN jsonb_array_elements(curriculum) s ON a.module_id=s->>'module' AND a.lesson_id=s->>'lesson'
 WHERE EXISTS(SELECT 1 FROM public.academy_lesson_audit h
   WHERE h.academy_lesson_id=a.id AND h.version_id=a.published_version_id
     AND h.action='saved' AND h.details->>'release'=release_name);
 IF already_applied=74 THEN RETURN; END IF;
 IF already_applied<>0 THEN RAISE EXCEPTION 'Partial full-course editorial release'; END IF;
 SELECT count(*) INTO eligible FROM public.academy_lessons a
 JOIN public.academy_lesson_versions b ON b.id=a.published_version_id
 JOIN jsonb_array_elements(curriculum) s ON a.module_id=s->>'module' AND a.lesson_id=s->>'lesson'
 WHERE b.change_note=s->>'base' AND b.version_number=(s->>'version')::integer;
 IF eligible=0 THEN
   RAISE NOTICE 'Expected published curriculum absent; no full-course editorial changes';
   RETURN;
 END IF;
 IF eligible<>74 THEN RAISE EXCEPTION 'Expected 74 source lessons after M01/M02 release, found %',eligible; END IF;
 SELECT md5(coalesce(jsonb_agg(to_jsonb(p) ORDER BY p.user_id,p.academy_lesson_id),'[]')::text)
   INTO initial_progress FROM public.academy_lesson_progress p;
 SELECT md5(coalesce(jsonb_agg(to_jsonb(a) ORDER BY a.id),'[]')::text)
   INTO initial_attempts FROM public.academy_lesson_attempts_v2 a;

 FOR spec IN SELECT value FROM jsonb_array_elements(curriculum) LOOP
   SELECT * INTO l FROM public.academy_lessons
     WHERE module_id=spec->>'module' AND lesson_id=spec->>'lesson' FOR UPDATE;
   SELECT * INTO v FROM public.academy_lesson_versions WHERE id=l.published_version_id FOR UPDATE;
   IF l.status<>'published' OR l.draft_version_id IS DISTINCT FROM l.published_version_id
      OR v.change_note<>spec->>'base' OR v.version_number<>(spec->>'version')::integer THEN
     RAISE EXCEPTION 'Publication drift for %/%',l.module_id,l.lesson_id;
   END IF;
   SELECT b.id INTO intro_id FROM public.academy_lesson_blocks b
     WHERE b.version_id=v.id AND b.block_key='objective' AND b.block_type='objective';
   IF intro_id IS NULL THEN RAISE EXCEPTION 'Opening missing for %',l.lesson_id; END IF;
   SELECT array_agg(b.id ORDER BY b.position),
     jsonb_build_object('version',to_jsonb(v),'blocks',jsonb_agg(to_jsonb(b)
       ||jsonb_build_object('evaluation',coalesce(k.answer_key,'{}'::jsonb),
         'feedback',coalesce(k.feedback,'{}'::jsonb),'scoring',coalesce(k.scoring,'{}'::jsonb)) ORDER BY b.position)),
     jsonb_agg(jsonb_build_object('id',b.id,'key',b.block_key,'type',b.block_type,
       'required',b.required,'points',b.points,
       'assessment',CASE WHEN b.block_type IN ('quiz','scenario','client_simulation','decision_tree',
         'matching','sequence_sort','calculator','image_hotspot','course_exam')
         THEN jsonb_build_object('content',b.content,'key',to_jsonb(k)) ELSE NULL END) ORDER BY b.block_key)
   INTO old_ids,before_image,preserved FROM public.academy_lesson_blocks b
   LEFT JOIN academy_private.lesson_block_keys k ON k.block_id=b.id WHERE b.version_id=v.id;
   INSERT INTO public.academy_lesson_audit(academy_lesson_id,version_id,action,details)
   VALUES(l.id,v.id,'saved',jsonb_build_object('release',release_name,
     'mode','compatible_editorial_supplement','before',before_image,
     'preserved_assessments',true,'progress_unchanged',true,'new_activities_optional',true));

   UPDATE public.academy_lesson_blocks SET title='Какво ще можеш след урока',content=spec->'intro'
     WHERE id=intro_id;
   UPDATE public.academy_lesson_versions
     SET title=coalesce(spec->>'title',title),objective=spec->'intro'->>'body',change_note=release_name
     WHERE id=v.id;
   -- Only plain unassessed body/title text; URLs and private assessment keys stay intact.
   UPDATE public.academy_lesson_blocks
     SET title=regexp_replace(title,'\mreaddy( ai)?\M(?![./])','избрания редактор','gi'),
         content=CASE WHEN jsonb_typeof(content->'body')='string' THEN jsonb_set(content,'{body}',
           to_jsonb(regexp_replace(content->>'body','\mreaddy( ai)?\M(?![./])','избрания редактор','gi')))
           ELSE content END
     WHERE version_id=v.id AND id<>intro_id AND block_type IN
       ('hook','concept','rich_text','case_study','example','summary','practical_response');

   IF spec ? 'exercise' THEN
     IF EXISTS(SELECT 1 FROM public.academy_lesson_blocks
       WHERE version_id=v.id AND block_key IN ('context_20261003','practice_20261003')) THEN
       RAISE EXCEPTION 'Unexpected existing supplement for %',l.lesson_id;
     END IF;
     UPDATE public.academy_lesson_blocks SET position=position+10000 WHERE version_id=v.id;
     UPDATE public.academy_lesson_blocks SET position=(position-10000)*10 WHERE version_id=v.id;
     SELECT position-4 INTO context_position FROM public.academy_lesson_blocks
       WHERE version_id=v.id AND block_key='practice_brief';
     SELECT position-2 INTO practice_position FROM public.academy_lesson_blocks
       WHERE version_id=v.id AND block_key='model_solution';
     IF context_position IS NULL OR practice_position IS NULL THEN
       RAISE EXCEPTION 'Practice structure missing for %',l.lesson_id;
     END IF;
     INSERT INTO public.academy_lesson_blocks(version_id,block_key,position,block_type,title,content,required,points)
     VALUES(v.id,'context_20261003',context_position,'rich_text',spec->>'context_title',spec->'context',false,0);
     INSERT INTO public.academy_lesson_blocks(version_id,block_key,position,block_type,title,content,required,points)
     VALUES(v.id,'practice_20261003',practice_position,spec->'exercise'->>'type',
       'Самопроверка по избор — нов практически случай',spec->'exercise'->'content',false,0)
     RETURNING id INTO practice_id;
     INSERT INTO academy_private.lesson_block_keys(block_id,answer_key,feedback,scoring)
     VALUES(practice_id,spec->'exercise'->'evaluation',spec->'exercise'->'feedback','{}'::jsonb);
   END IF;

   SELECT jsonb_agg(jsonb_build_object('id',b.id,'key',b.block_key,'type',b.block_type,
     'required',b.required,'points',b.points,
     'assessment',CASE WHEN b.block_type IN ('quiz','scenario','client_simulation','decision_tree',
       'matching','sequence_sort','calculator','image_hotspot','course_exam')
       THEN jsonb_build_object('content',b.content,'key',to_jsonb(k)) ELSE NULL END) ORDER BY b.block_key)
   INTO after_preserved FROM public.academy_lesson_blocks b
   LEFT JOIN academy_private.lesson_block_keys k ON k.block_id=b.id WHERE b.id=ANY(old_ids);
   IF preserved IS DISTINCT FROM after_preserved THEN RAISE EXCEPTION 'Assessment/progress contract changed for %',l.lesson_id; END IF;
   IF EXISTS(SELECT 1 FROM public.academy_lesson_blocks
     WHERE version_id=v.id AND NOT(id=ANY(old_ids)) AND (required OR points<>0)) THEN
     RAISE EXCEPTION 'New steps must remain optional with zero XP';
   END IF;
   result:=academy_private.lesson_validation(v.id);
   IF jsonb_array_length(result->'errors')>0 THEN RAISE EXCEPTION 'Invalid %: %',l.lesson_id,result; END IF;
   UPDATE public.academy_lesson_versions SET validation=result WHERE id=v.id;
 END LOOP;
 IF initial_progress IS DISTINCT FROM (SELECT md5(coalesce(jsonb_agg(to_jsonb(p) ORDER BY p.user_id,p.academy_lesson_id),'[]')::text) FROM public.academy_lesson_progress p)
   OR initial_attempts IS DISTINCT FROM (SELECT md5(coalesce(jsonb_agg(to_jsonb(a) ORDER BY a.id),'[]')::text) FROM public.academy_lesson_attempts_v2 a) THEN
   RAISE EXCEPTION 'Learner records changed; abort the entire release';
 END IF;
END $editorial$;
